// Stats — nol qiymati ishlatishga tayyor: NewStats() kerak emas
type Stats struct {
	mu    sync.Mutex
	count int
	sum   float64
	tags  map[string]int
}

func (s *Stats) Add(v float64, tag string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.tags == nil {
		s.tags = make(map[string]int) // birinchi yozishda yaratiladi
	}
	s.count++
	s.sum += v
	s.tags[tag]++
}

func (s *Stats) Mean() float64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.count == 0 {
		return 0 // bo'sh holat ham to'g'ri ishlaydi
	}
	return s.sum / float64(s.count)
}

func (s *Stats) Tag(name string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.tags[name] // nil map'dan o'qish xavfsiz
}

type Server struct {
	Name  string
	Stats Stats // ichki maydon ham nol qiymatda tayyor
}

func main() {
	var srv Server
	fmt.Println(srv.Stats.Mean(), srv.Stats.Tag("api"))

	srv.Stats.Add(120, "api")
	srv.Stats.Add(80, "api")
	srv.Stats.Add(40, "web")
	fmt.Println(srv.Stats.Mean(), srv.Stats.Tag("api"))
}

