import "fmt"

type Node struct {
	Val         int
	Left, Right *Node
}

// Sum nil daraxt uchun ham ishlaydi — chaqiruvchi nil tekshirmaydi
func (n *Node) Sum() int {
	if n == nil {
		return 0
	}
	return n.Val + n.Left.Sum() + n.Right.Sum()
}

func (n *Node) Depth() int {
	if n == nil {
		return 0
	}
	return 1 + max(n.Left.Depth(), n.Right.Depth())
}

func main() {
	var empty *Node
	fmt.Println(empty.Sum(), empty.Depth())

	tree := &Node{
		Val:   5,
		Left:  &Node{Val: 3, Left: &Node{Val: 1}},
		Right: &Node{Val: 8},
	}
	fmt.Println(tree.Sum(), tree.Depth())
}

