// Yomon: har bir shart yangi daraja qo'shadi
func validateNested(s Signup) error {
	if strings.Contains(s.Email, "@") {
		if len(s.Password) >= 8 {
			if s.Age >= 16 {
				return nil
			} else {
				return errors.New("yosh kamida 16")
			}
		} else {
			return errors.New("parol kamida 8 belgi")
		}
	} else {
		return errors.New("email noto'g'ri")
	}
}

// Yaxshi: har bir xato darhol qaytadi, else yo'q
func validate(s Signup) error {
	if !strings.Contains(s.Email, "@") {
		return errors.New("email noto'g'ri")
	}
	if len(s.Password) < 8 {
		return errors.New("parol kamida 8 belgi")
	}
	if s.Age < 16 {
		return errors.New("yosh kamida 16")
	}
	return nil
}

func main() {
	cases := []Signup{
		{"ali@mail.uz", "secret123", 20},
		{"ali.mail.uz", "secret123", 20},
		{"ali@mail.uz", "123", 20},
		{"ali@mail.uz", "secret123", 12},
	}
	for _, c := range cases {
		fmt.Println(validateNested(c), "|", validate(c))
	}
}

