import (
	"fmt"
	"strconv"
	"strings"
)

// parsePort "port=8080" ko'rinishidagi qatordan port raqamini oladi.
func parsePort(line string) (int, error) {
	key, value, ok := strings.Cut(line, "=")
	if !ok {
		return 0, fmt.Errorf("%q: '=' belgisi yo'q", line)
	}
	if key != "port" {
		return 0, fmt.Errorf("%q: kutilmagan kalit %q", line, key)
	}
	port, err := strconv.Atoi(value)
	if err != nil {
		return 0, fmt.Errorf("%q: port son emas: %w", line, err)
	}
	if port < 1 || port > 65535 {
		return 0, fmt.Errorf("%q: port 1..65535 oralig'ida bo'lsin", line)
	}
	return port, nil // baxtli yo'l — oxirida, chap chekkada
}

func main() {
	lines := []string{"port=8080", "port8080", "host=x", "port=abc", "port=70000"}
	for _, line := range lines {
		port, err := parsePort(line)
		if err != nil {
			fmt.Println("xato:", err)
			continue
		}
		fmt.Println("port:", port)
	}
}

