// Yaxshi: xato chaqiruvchiga kontekst bilan qaytariladi
func sum(items []string) (int, error) {
	total := 0
	for i, s := range items {
		n, err := strconv.Atoi(s)
		if err != nil {
			return 0, fmt.Errorf("element %d (%q): %w", i, s, err)
