import "fmt"

func unique(words []string) []string {
	seen := make(map[string]bool, len(words))
	out := make([]string, 0, len(words))
	for _, w := range words {
		if seen[w] { // yo'q kalit -> false
			continue
		}
		seen[w] = true
		out = append(out, w)
	}
	return out
}

