package main

import (
	"errors"
	"fmt"
	"sync"
)

var ErrInsufficient = errors.New("mablag' yetarli emas")

type Account struct {
	mu      sync.Mutex
	balance int
}

func (a *Account) Withdraw(amount int) error {
	a.mu.Lock()
	defer a.mu.Unlock() // erta return'da ham qulf ochiladi
	if amount > a.balance {
		return ErrInsufficient
	}
	a.balance -= amount
	return nil
}

func (a *Account) Balance() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.balance
}

func main() {
	acc := &Account{balance: 100}
	errs := make(chan error, 5)
	var wg sync.WaitGroup
	for range 5 {
		wg.Go(func() { errs <- acc.Withdraw(30) })
	}
	wg.Wait()
	close(errs)

	failed := 0
	for err := range errs {
		if errors.Is(err, ErrInsufficient) {
			failed++
		}
	}
	fmt.Println("qoldiq:", acc.Balance(), "rad etildi:", failed)
}

