type Item struct {
	Name  string
	Price int
}

// io.Writer qabul qiladi: terminal, fayl, bufer, HTTP javob — hammasiga yoza oladi
func writeReceipt(w io.Writer, items []Item) error {
	total := 0
	for _, it := range items {
		if _, err := fmt.Fprintf(w, "%-6s %5d\n", it.Name, it.Price); err != nil {
			return err
		}
		total += it.Price
	}
	_, err := fmt.Fprintf(w, "%-6s %5d\n", "JAMI", total)
	return err
}

func main() {
	items := []Item{{"non", 4000}, {"sut", 12000}}
	if err := writeReceipt(os.Stdout, items); err != nil {
		fmt.Println("xato:", err)
	}

	var buf bytes.Buffer // testda natijani tekshirish uchun
	if err := writeReceipt(&buf, items); err != nil {
		fmt.Println("xato:", err)
	}
	fmt.Println("buferda", strings.Count(buf.String(), "\n"), "qator")
}

