import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"strings"
)

// countLines istalgan io.Reader dan qatorlarni sanaydi
func countLines(r io.Reader) (int, error) {
	sc := bufio.NewScanner(r)
	n := 0
	for sc.Scan() {
		n++
	}
	return n, sc.Err()
}

// repeat — o'z Reader'imiz: bitta baytni n marta beradi
type repeat struct {
	b byte
	n int
}

func (r *repeat) Read(p []byte) (int, error) {
	if r.n == 0 {
		return 0, io.EOF
	}
	k := min(len(p), r.n)
	for i := range k {
		p[i] = r.b
	}
	r.n -= k
	return k, nil
}

func main() {
	sources := []io.Reader{
		strings.NewReader("bir\nikki\nuch\n"),
		bytes.NewBufferString("faqat bitta qator"),
		&repeat{b: '\n', n: 4},
		io.MultiReader(strings.NewReader("a\n"), strings.NewReader("b\n")),
	}
	for _, src := range sources {
		fmt.Println(countLines(src))
	}
}

