import (
	"errors"
	"fmt"
	"strings"
)

type Validator interface {
	Validate(s string) error
}

// ValidatorFunc oddiy funksiyani Validator'ga aylantiradi
type ValidatorFunc func(string) error

func (f ValidatorFunc) Validate(s string) error { return f(s) }

func check(s string, vs ...Validator) []string {
	var problems []string
	for _, v := range vs {
		if err := v.Validate(s); err != nil {
			problems = append(problems, err.Error())
		}
	}
	return problems
}

func maxLen(n int) Validator {
	return ValidatorFunc(func(s string) error {
		if len(s) > n {
			return fmt.Errorf("%d belgidan uzun", n)
		}
		return nil
	})
}

var notEmpty = ValidatorFunc(func(s string) error {
	if strings.TrimSpace(s) == "" {
		return errors.New("bo'sh")
	}
	return nil
})

func main() {
	fmt.Println(check("gopher", notEmpty, maxLen(10)))
	fmt.Println(check("   ", notEmpty, maxLen(2)))
}

