var words = strings.Fields("go oddiy tez ishonchli va o'qishga qulay til")

// Yomon: har bir += yangi satr yaratadi va eskisini nusxalaydi
func joinPlus(ws []string) string {
	s := ""
	for _, w := range ws {
		s += w + " "
	}
	return s
}

// Yaxshi: Builder bitta buferga yozadi, Grow uni oldindan ajratadi
func joinBuilder(ws []string) string {
	n := 0
	for _, w := range ws {
		n += len(w) + 1
	}
	var sb strings.Builder
	sb.Grow(n)
	for _, w := range ws {
		sb.WriteString(w)
		sb.WriteByte(' ')
	}
	return sb.String()
}

func main() {
	fmt.Println(joinPlus(words) == joinBuilder(words))
	plus := testing.AllocsPerRun(100, func() { joinPlus(words) })
	builder := testing.AllocsPerRun(100, func() { joinBuilder(words) })
	fmt.Println("+= allokatsiyalari:", plus)
	fmt.Println("Builder allokatsiyalari:", builder)
}

