import "fmt"

// grow n ta element qo'shadi va massiv necha marta qayta ajratilganini sanaydi
func grow(s []int, n int) ([]int, int) {
	reallocs := 0
	for i := range n {
		before := cap(s)
		s = append(s, i)
		if cap(s) != before {
			reallocs++
		}
	}
	return s, reallocs
}

func main() {
	const n = 10_000

	var a []int // hajm noma'lum — append o'zi kattalashtiradi
	a, r1 := grow(a, n)
	fmt.Println("oldindan ajratmasdan:", len(a), "element,", r1, "marta qayta ajratildi")

	b := make([]int, 0, n) // hajm ma'lum — bitta ajratish
	b, r2 := grow(b, n)
	fmt.Println("make(0, n) bilan:", len(b), "element,", r2, "marta qayta ajratildi")
}

