import "fmt"

// Xato: uzunlik = len(nums), ichi nollar; append ulardan keyin qo'shadi
func squaresBad(nums []int) []int {
	out := make([]int, len(nums))
	for _, n := range nums {
		out = append(out, n*n)
	}
	return out
}

// To'g'ri 1: uzunlik 0, sig'im n — append bilan
func squares(nums []int) []int {
	out := make([]int, 0, len(nums))
	for _, n := range nums {
		out = append(out, n*n)
	}
	return out
}

// To'g'ri 2: uzunlik n — indeks bilan yozish
func squaresIdx(nums []int) []int {
	out := make([]int, len(nums))
	for i, n := range nums {
		out[i] = n * n
	}
	return out
}

func main() {
	nums := []int{1, 2, 3}
	fmt.Println(squaresBad(nums))
	fmt.Println(squares(nums))
	fmt.Println(squaresIdx(nums))
}

