// counter cheksiz qiymat chiqaradi, lekin ctx bekor qilinsa to'xtaydi
func counter(ctx context.Context) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		defer fmt.Println("counter goroutine tugadi")
		for i := 0; ; i++ {
			select {
			case out <- i:
			case <-ctx.Done(): // chiqish yo'li — goroutine oqib qolmaydi
				return
			}
		}
	}()
	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	nums := counter(ctx)
	for range 3 {
		fmt.Println(<-nums)
	}
	cancel()
	for range nums {
		// qolgan qiymatlarni tashlab, kanal yopilishini kutamiz
	}
	fmt.Println("main tugadi")
}

