import (
	"fmt"
	"sync"
)

// Kanal bilan: alohida "egasi" goroutine kerak — oddiy hisoblagich uchun ortiqcha
func countWithChannel(n int) int {
	inc := make(chan struct{})
	done := make(chan int)
	go func() {
		total := 0
		for range inc {
			total++
		}
		done <- total
	}()
	var wg sync.WaitGroup
	for range n {
		wg.Go(func() { inc <- struct{}{} })
	}
	wg.Wait()
	close(inc)
	return <-done
}

// Mutex bilan: umumiy holatni himoyalash — sodda va tushunarli
type Hits struct {
	mu sync.Mutex
	n  int
}

func (h *Hits) Inc() {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.n++
}

func countWithMutex(n int) int {
	var h Hits
	var wg sync.WaitGroup
	for range n {
		wg.Go(h.Inc)
	}
	wg.Wait()
	return h.n
}

func main() {
	fmt.Println(countWithChannel(1000), countWithMutex(1000))
}

