import "fmt"

// Yomon: any qabul qiladi — noto'g'ri tip faqat ish vaqtida aniqlanadi
func sumAny(values []any) (float64, error) {
	total := 0.0
	for _, v := range values {
		switch n := v.(type) {
		case int:
			total += float64(n)
		case float64:
			total += n
		default:
			return 0, fmt.Errorf("qo'llab-quvvatlanmaydigan tip: %T", v)
		}
	}
	return total, nil
}

// Yaxshi: tip cheklovi — xato kompilyatsiya vaqtida ushlanadi
type Number interface {
	~int | ~int64 | ~float64
}

func Sum[T Number](values []T) T {
	var total T
	for _, v := range values {
		total += v
	}
	return total
}

func main() {
	fmt.Println(sumAny([]any{1, 2.5, "3"}))
	fmt.Println(Sum([]int{1, 2, 3}), Sum([]float64{1.5, 2.5}))
	// Sum([]string{"a"}) — kompilyatsiya xatosi: string Number emas
}

