import (
	"cmp"
	"errors"
	"fmt"
	"io"
	"maps"
	"os"
	"slices"
	"strconv"
	"strings"
)

type Sale struct {
	Region string
	Amount int
}

// parseSales "hudud,summa" qatorlarini o'qiydi.
func parseSales(input string) ([]Sale, error) {
	lines := strings.Split(strings.TrimSpace(input), "\n")
	sales := make([]Sale, 0, len(lines))
	for i, line := range lines {
		region, amountStr, ok := strings.Cut(line, ",")
		if !ok {
			return nil, fmt.Errorf("qator %d: vergul yo'q", i+1)
		}
		amount, err := strconv.Atoi(strings.TrimSpace(amountStr))
		if err != nil {
			return nil, fmt.Errorf("qator %d: %w", i+1, err)
		}
		sales = append(sales, Sale{strings.TrimSpace(region), amount})
	}
	return sales, nil
}

// writeReport hududlar bo'yicha jami summani kamayish tartibida yozadi.
func writeReport(w io.Writer, sales []Sale) error {
	if len(sales) == 0 {
		return errors.New("hisobot: ma'lumot yo'q")
	}
	totals := make(map[string]int)
	for _, s := range sales {
		totals[s.Region] += s.Amount // yangi kalit 0 dan boshlanadi
	}
	regions := slices.Collect(maps.Keys(totals))
	slices.SortFunc(regions, func(a, b string) int {
		return cmp.Or(cmp.Compare(totals[b], totals[a]), cmp.Compare(a, b))
	})
	var sb strings.Builder
	for _, r := range regions {
		fmt.Fprintf(&sb, "%-10s %6d\n", r, totals[r])
	}
	_, err := io.WriteString(w, sb.String())
	return err
}

func main() {
	input := "Toshkent, 1200\nSamarqand, 800\nToshkent, 300\nBuxoro, 800"
	sales, err := parseSales(input)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := writeReport(os.Stdout, sales); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	_, err = parseSales("Xiva 100")
	fmt.Println("xato:", err)
}

