)

var ErrNotFound = errors.New("topilmadi")

type Book struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
}

// bookFinder — handler'ga kerakli yagona metod (consumer tomonida)
type bookFinder interface {
	Find(id int) (Book, error)
}

// MemStore — konkret tip: interfeys e'lon qilmaydi va qaytarmaydi
type MemStore struct {
	mu    sync.RWMutex
	books map[int]Book
}

func (s *MemStore) Find(id int) (Book, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	b, ok := s.books[id]
	if !ok {
		return Book{}, ErrNotFound
	}
	return b, nil
}

func bookHandler(store bookFinder) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(r.PathValue("id"))
		if err != nil {
			http.Error(w, "id son bo'lishi kerak", http.StatusBadRequest)
			return
		}
		book, err := store.Find(id)
		if errors.Is(err, ErrNotFound) {
			http.Error(w, "kitob topilmadi", http.StatusNotFound)
			return
		}
		if err != nil {
			http.Error(w, "ichki xato", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(book)
	}
}

func main() {
	store := &MemStore{books: map[int]Book{1: {ID: 1, Title: "Effective Go"}}}
	mux := http.NewServeMux()
	mux.Handle("GET /books/{id}", bookHandler(store))

	for _, path := range []string{"/books/1", "/books/2", "/books/abc"} {
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
		fmt.Printf("%s -> %d %s", path, rec.Code, rec.Body.String())
	}
}

