type Option func(*config) error

func WithPort(port int) Option {
	return func(c *config) error {
		if port < 1 || port > 65535 {
			return fmt.Errorf("WithPort(%d): 1..65535 oralig'ida bo'lishi kerak", port)
		}
		c.port = port
		return nil
	}
}

func New(addr string, opts ...Option) (*Server, error) {
	c := defaultConfig()
	for _, opt := range opts {
		if err := opt(&c); err != nil {
			return nil, fmt.Errorf("server: %w", err)
		}
	}
	if c.minConns > c.maxConns { // o'zaro bog'liq maydonlar — hamma option'dan keyin
		return nil, errors.New("server: minConns > maxConns")
	}
	return &Server{addr: addr, cfg: c}, nil
}

type Option interface {
	apply(*options) // kichik harf: tashqi paket o'z Option'ini yasay olmaydi
}

type funcOption func(*options)

func (f funcOption) apply(o *options) { f(o) }

func WithTimeout(d time.Duration) Option {
	return funcOption(func(o *options) { o.timeout = d })
}

