import (
	"errors"
	"fmt"
	"strings"
)

type QueryBuilder struct {
	table string
	where []string
	limit int
	errs  []error
}

func From(table string) *QueryBuilder {
	b := &QueryBuilder{table: table}
	if table == "" {
		b.errs = append(b.errs, errors.New("jadval nomi bo'sh"))
	}
	return b
}

func (b *QueryBuilder) Where(cond string) *QueryBuilder {
	if strings.TrimSpace(cond) == "" {
		b.errs = append(b.errs, errors.New("bo'sh shart"))
		return b
	}
	b.where = append(b.where, cond)
	return b
}

func (b *QueryBuilder) Limit(n int) *QueryBuilder {
	if n <= 0 {
		b.errs = append(b.errs, fmt.Errorf("limit musbat bo'lishi kerak: %d", n))
		return b
	}
	b.limit = n
	return b
}

func (b *QueryBuilder) Build() (string, error) {
	if err := errors.Join(b.errs...); err != nil {
		return "", err
	}
	sql := "SELECT * FROM " + b.table
	if len(b.where) > 0 {
		sql += " WHERE " + strings.Join(b.where, " AND ")
	}
	if b.limit > 0 {
		sql += fmt.Sprintf(" LIMIT %d", b.limit)
	}
	return sql, nil
}

func main() {
	sql, err := From("users").Where("age > 18").Where("active = true").Limit(10).Build()
	fmt.Println(sql, err)

	_, err = From("").Where(" ").Limit(-1).Build()
	fmt.Println("xatolar:")
	fmt.Println(err)
}

