type config struct {
	name    string
	workers int
	queue   string
}

type Option func(*config) error

func WithName(n string) Option {
	return func(c *config) error {
		if strings.TrimSpace(n) == "" {
			return errors.New("name: bo'sh")
		}
		c.name = n
		return nil
	}
}

func WithWorkers(n int) Option {
	return func(c *config) error {
		if n < 1 || n > 64 {
			return fmt.Errorf("workers: %d (1..64 kerak)", n)
		}
		c.workers = n
		return nil
	}
}

func WithQueue(q string) Option {
	return func(c *config) error {
		if !strings.HasPrefix(q, "queue.") {
			return fmt.Errorf("queue: %q \"queue.\" bilan boshlanmaydi", q)
		}
		c.queue = q
		return nil
	}
}

func NewPool(opts ...Option) (*config, error) {
	c := &config{name: "pool", workers: 4, queue: "queue.default"}
	var errs []error
	for _, opt := range opts {
		if err := opt(c); err != nil {
			errs = append(errs, err) // to'xtamaymiz — hammasini yig'amiz
		}
	}
	if err := errors.Join(errs...); err != nil {
		return nil, fmt.Errorf("pool sozlamalari noto'g'ri:\n%w", err)
	}
	return c, nil
}

func main() {
	c, err := NewPool(WithWorkers(8))
	fmt.Printf("%+v %v\n", *c, err)

	_, err = NewPool(WithName(" "), WithWorkers(100), WithQueue("jobs"))
	fmt.Println(err)
}

