import "fmt"

type Logger struct {
	verbosity int
	prefix    string
}

// option o'zini bekor qiladigan option'ni qaytaradi.
type option func(*Logger) option

func Verbosity(v int) option {
	return func(l *Logger) option {
		prev := l.verbosity
		l.verbosity = v
		return Verbosity(prev) // oldingi holatni tiklaydigan option
	}
}

func Prefix(p string) option {
	return func(l *Logger) option {
		prev := l.prefix
		l.prefix = p
		return Prefix(prev)
	}
}

// Option option'larni qo'llaydi va oxirgisini bekor qiluvchini qaytaradi.
func (l *Logger) Option(opts ...option) (previous option) {
	for _, opt := range opts {
		previous = opt(l)
	}
	return previous
}

func (l *Logger) Log(level int, msg string) {
	if level <= l.verbosity {
		fmt.Println(l.prefix + msg)
	}
}

func main() {
	l := &Logger{verbosity: 1, prefix: "[app] "}
	l.Log(1, "info: ishga tushdi")
	l.Log(2, "debug: ko'rinmaydi")

	func() {
		prev := l.Option(Verbosity(3)) // vaqtincha batafsil rejim
		defer l.Option(prev)           // funksiya tugaganda eski holat
		l.Log(2, "debug: endi ko'rinadi")
	}()

	l.Log(2, "debug: yana yashirin")
	fmt.Println("verbosity:", l.verbosity)
}

