	Roles []string `json:"roles"`
}

func main() {
	u := User{Name: "Aziz"} // Roles — nil slice
	m := map[string]int{"b": 2, "a": 1, "c": 3}

	b, _ := json.Marshal(u) // option'larsiz: nil slice — []
	fmt.Println(string(b))

	b, _ = json.Marshal(m, json.Deterministic(true), jsontext.WithIndent("  "))
	fmt.Println(string(b))

	// JoinOptions bir nechta option'ni bitta preset'ga birlashtiradi
	legacy := json.JoinOptions(json.Deterministic(true), json.FormatNilSliceAsNull(true))
	b, _ = json.Marshal(u, legacy)
	fmt.Println(string(b))

	v, ok := json.GetOption(legacy, json.FormatNilSliceAsNull)
	fmt.Println("FormatNilSliceAsNull:", v, ok)
}

