)

type Token struct {
	Value     string
	ExpiresAt time.Time
}

type Issuer struct {
	ttl time.Duration
	now func() time.Time // bog'liqlik: vaqt manbai
}

type Option func(*Issuer)

func WithTTL(d time.Duration) Option        { return func(i *Issuer) { i.ttl = d } }
func WithClock(now func() time.Time) Option { return func(i *Issuer) { i.now = now } }

func NewIssuer(opts ...Option) *Issuer {
	i := &Issuer{ttl: time.Hour, now: time.Now} // productionda haqiqiy soat
	for _, opt := range opts {
		opt(i)
	}
	return i
}

func (i *Issuer) Issue(user string) Token {
	return Token{Value: "tok-" + user, ExpiresAt: i.now().Add(i.ttl)}
}

func (i *Issuer) Valid(t Token) bool { return i.now().Before(t.ExpiresAt) }

func main() {
	current := time.Date(2026, 1, 15, 9, 0, 0, 0, time.UTC)
	iss := NewIssuer(WithTTL(30*time.Minute), WithClock(func() time.Time { return current }))

	tok := iss.Issue("aziz")
	fmt.Println(tok.Value, tok.ExpiresAt.Format(time.DateTime))
	fmt.Println("09:00 da yaroqli:", iss.Valid(tok))

	current = current.Add(31 * time.Minute) // vaqtni "oldinga suramiz"
	fmt.Println("09:31 da yaroqli:", iss.Valid(tok))
}

