package main

import (
	"errors"
	"fmt"
	"time"
)

type Retrier struct {
	attempts int
	backoff  func(attempt int) time.Duration
	sleep    func(time.Duration)
}

type Option func(*Retrier)

func WithAttempts(n int) Option                    { return func(r *Retrier) { r.attempts = n } }
func WithBackoff(f func(int) time.Duration) Option { return func(r *Retrier) { r.backoff = f } }
func WithSleep(f func(time.Duration)) Option       { return func(r *Retrier) { r.sleep = f } }

// Exponential: base, 2*base, 4*base, ...
func Exponential(base time.Duration) func(int) time.Duration {
	return func(attempt int) time.Duration { return base << (attempt - 1) }
}

func NewRetrier(opts ...Option) *Retrier {
	r := &Retrier{attempts: 3, backoff: Exponential(100 * time.Millisecond), sleep: time.Sleep}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

func (r *Retrier) Do(op func() error) error {
	var err error
	for attempt := 1; attempt <= r.attempts; attempt++ {
		if err = op(); err == nil {
			return nil
		}
		if attempt < r.attempts {
			r.sleep(r.backoff(attempt))
		}
	}
	return fmt.Errorf("%d urinishdan keyin: %w", r.attempts, err)
}

func main() {
	var waits []time.Duration
	fake := WithSleep(func(d time.Duration) { waits = append(waits, d) })

	calls := 0
	err := NewRetrier(WithAttempts(5), fake).Do(func() error {
		calls++
		if calls < 4 {
			return errors.New("vaqtinchalik xato")
		}
		return nil
	})
	fmt.Println("natija:", err, "chaqiruvlar:", calls, "kutishlar:", waits)

	waits = nil
	constant := WithBackoff(func(int) time.Duration { return time.Second })
	err = NewRetrier(fake, constant).Do(func() error { return errors.New("server ishlamayapti") })
	fmt.Println("natija:", err, "kutishlar:", waits)
}

