import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

type Middleware func(http.Handler) http.Handler

type Server struct {
	mux         *http.ServeMux
	middlewares []Middleware
}

type Option func(*Server)

// WithMiddleware bir necha marta berilishi mumkin; berilgan tartibda o'raladi.
func WithMiddleware(m ...Middleware) Option {
	return func(s *Server) { s.middlewares = append(s.middlewares, m...) }
}

func WithRoute(pattern string, h http.HandlerFunc) Option {
	return func(s *Server) { s.mux.HandleFunc(pattern, h) }
}

func NewServer(opts ...Option) http.Handler {
	s := &Server{mux: http.NewServeMux()}
	for _, opt := range opts {
		opt(s)
	}
	var h http.Handler = s.mux
	for i := len(s.middlewares) - 1; i >= 0; i-- { // birinchi berilgan — eng tashqi
		h = s.middlewares[i](h)
	}
	return h
}

func tag(name string) Middleware {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			fmt.Fprintf(w, "%s> ", name)
			next.ServeHTTP(w, r)
			fmt.Fprintf(w, " <%s", name)
		})
	}
}

func main() {
	h := NewServer(
		WithMiddleware(tag("log"), tag("auth")),
		WithRoute("GET /hello", func(w http.ResponseWriter, r *http.Request) { io.WriteString(w, "salom") }),
		WithMiddleware(tag("gzip")),
	)

	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/hello", nil))
	fmt.Println(rec.Code, rec.Body.String())
}

