import (
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"time"
)

type Config struct {
	Port    int           `json:"port"`
	Timeout time.Duration `json:"-"`
	Env     string        `json:"env"`
}

type Option func(*Config) error

// FromJSON — 2-qatlam: fayl (bu yerda satr).
func FromJSON(data []byte) Option {
	return func(c *Config) error { return json.Unmarshal(data, c) }
}

// FromEnv — 3-qatlam: muhit o'zgaruvchilari, faqat mavjudlari.
func FromEnv(prefix string) Option {
	return func(c *Config) error {
		if v, ok := os.LookupEnv(prefix + "PORT"); ok {
			p, err := strconv.Atoi(v)
			if err != nil {
				return fmt.Errorf("%sPORT: %w", prefix, err)
			}
			c.Port = p
		}
		if v, ok := os.LookupEnv(prefix + "TIMEOUT"); ok {
			d, err := time.ParseDuration(v)
			if err != nil {
				return fmt.Errorf("%sTIMEOUT: %w", prefix, err)
			}
			c.Timeout = d
		}
		return nil
	}
}

// WithPort — 4-qatlam: koddagi aniq qiymat (masalan, flag'dan).
func WithPort(p int) Option {
	return func(c *Config) error {
		c.Port = p
		return nil
	}
}

func Load(opts ...Option) (Config, error) {
	c := Config{Port: 8080, Timeout: 30 * time.Second, Env: "dev"} // 1-qatlam: default
	for _, opt := range opts {
		if err := opt(&c); err != nil {
			return Config{}, fmt.Errorf("config: %w", err)
		}
	}
	return c, nil
}

func main() {
	file := []byte(`{"port": 9000, "env": "prod"}`)
	os.Setenv("MYAPP_TIMEOUT", "5s")

	c, err := Load(FromJSON(file), FromEnv("MYAPP_"))
	fmt.Printf("%+v %v\n", c, err)

	c, err = Load(FromJSON(file), FromEnv("MYAPP_"), WithPort(9443))
	fmt.Printf("%+v %v\n", c, err)

	os.Setenv("MYAPP_PORT", "abc")
	_, err = Load(FromJSON(file), FromEnv("MYAPP_"))
	fmt.Println(err)
}

