	"net/url"
	"time"
)

type poolConfig struct {
	maxConns    int
	minConns    int
	maxIdleTime time.Duration
}

type Option func(*poolConfig) error

func WithMaxConns(n int) Option {
	return func(c *poolConfig) error {
		if n < 1 {
			return fmt.Errorf("WithMaxConns(%d): kamida 1", n)
		}
		c.maxConns = n
		return nil
	}
}

func WithMinConns(n int) Option {
	return func(c *poolConfig) error {
		if n < 0 {
			return fmt.Errorf("WithMinConns(%d): manfiy bo'lmasin", n)
		}
		c.minConns = n
		return nil
	}
}

type Pool struct {
	dsn *url.URL
	cfg poolConfig
}

// NewPool: dsn majburiy, qolganlari ixtiyoriy.
func NewPool(dsn string, opts ...Option) (*Pool, error) {
	u, err := url.Parse(dsn)
	if err != nil || u.Scheme != "postgres" {
		return nil, errors.New("pool: dsn postgres://... ko'rinishida bo'lishi kerak")
	}
	cfg := poolConfig{maxConns: 10, minConns: 0, maxIdleTime: 30 * time.Minute}
	for _, opt := range opts {
		if err := opt(&cfg); err != nil {
			return nil, fmt.Errorf("pool: %w", err)
		}
	}
	if cfg.minConns > cfg.maxConns {
		return nil, fmt.Errorf("pool: minConns %d > maxConns %d", cfg.minConns, cfg.maxConns)
	}
	return &Pool{dsn: u, cfg: cfg}, nil
}

// String parolni yashiradi — sozlamani log'ga yozish xavfsiz.
func (p *Pool) String() string {
	return fmt.Sprintf("dsn=%s max=%d min=%d idle=%v", p.dsn.Redacted(), p.cfg.maxConns, p.cfg.minConns, p.cfg.maxIdleTime)
}

func main() {
	const dsn = "postgres://app:s3cret@db.local:5432/shop"

	p, err := NewPool(dsn, WithMaxConns(20), WithMinConns(2))
	fmt.Println(p, err)

	_, err = NewPool(dsn, WithMinConns(50))
	fmt.Println(err)

	_, err = NewPool(dsn, WithMaxConns(0))
	fmt.Println(err)

	_, err = NewPool("mysql://localhost/shop")
	fmt.Println(err)
}

package main

import "fmt"

type config[K comparable, V any] struct {
	capacity int
	onEvict  func(K, V)
}

type Option[K comparable, V any] func(*config[K, V])

func WithCapacity[K comparable, V any](n int) Option[K, V] {
	return func(c *config[K, V]) { c.capacity = n }
}

func WithOnEvict[K comparable, V any](f func(K, V)) Option[K, V] {
	return func(c *config[K, V]) { c.onEvict = f }
}

type Cache[K comparable, V any] struct {
	cfg   config[K, V]
	items map[K]V
	order []K // qo'shilish tartibi (FIFO)
}

func New[K comparable, V any](opts ...Option[K, V]) *Cache[K, V] {
	cfg := config[K, V]{capacity: 100, onEvict: func(K, V) {}}
	for _, opt := range opts {
		opt(&cfg)
	}
	return &Cache[K, V]{cfg: cfg, items: make(map[K]V)}
}

func (c *Cache[K, V]) Set(k K, v V) {
	if _, ok := c.items[k]; !ok {
		if len(c.order) == c.cfg.capacity { // to'ldi — eng eskisini chiqaramiz
			old := c.order[0]
			c.order = c.order[1:]
			c.cfg.onEvict(old, c.items[old])
			delete(c.items, old)
		}
		c.order = append(c.order, k)
	}
	c.items[k] = v
}

func (c *Cache[K, V]) Get(k K) (V, bool) {
	v, ok := c.items[k]
	return v, ok
}

func main() {
	c := New(
		WithCapacity[string, int](2), // tipni argumentdan aniqlab bo'lmaydi
		WithOnEvict(func(k string, v int) { fmt.Println("chiqarildi:", k, v) }),
	)
	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("a", 10) // mavjud kalit — chiqarish yo'q
	c.Set("c", 3)  // sig'im 2 — eng eskisi (a) chiqadi

	fmt.Println(c.Get("a"))
	fmt.Println(c.Get("c"))
	fmt.Println("elementlar:", len(c.items), c.order)
}

