}

func NewTaskHandler(svc taskCreator) *TaskHandler { return &TaskHandler{svc: svc} }

// fayl: cmd/api/main.go
func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	if err := run(ctx, os.Args, os.Getenv, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(ctx context.Context, args []string, getenv func(string) string, out io.Writer) error {
	// 1. konfiguratsiya va logger
	cfg, err := config.Load(args, getenv)
	if err != nil {
		return err
	}
	log := slog.New(slog.NewJSONHandler(out, nil))

	// 2. driven adapterlar
	db, err := postgres.Open(ctx, cfg.DatabaseURL)
	if err != nil {
		return err
	}
	defer db.Close()

	// 3. yadro va 4. driving adapter
	orders := order.NewService(postgres.NewOrderRepo(db), smtp.NewMailer(cfg.SMTP), log)
	srv := &http.Server{Addr: cfg.Addr, Handler: httpapi.NewRouter(orders, log)}

	// 5. ishga tushirish (graceful shutdown bilan)
	return serve(ctx, srv)
}

// httpapi paketi: xato → status moslashtiriladigan YAGONA joy
func statusOf(err error) int {
	var ve *order.ValidationError
	switch {
	case errors.As(err, &ve):
		return http.StatusUnprocessableEntity // 422
	case errors.Is(err, order.ErrNotFound):
		return http.StatusNotFound // 404
	case errors.Is(err, order.ErrConflict):
		return http.StatusConflict // 409
	case errors.Is(err, context.DeadlineExceeded):
		return http.StatusGatewayTimeout // 504
	default:
		return http.StatusInternalServerError // 500: tafsilot faqat log'da
	}
}

