type Deps struct {
	Orders   OrderRepo
	Payments Payments
	Notifier Notifier
	Now      func() time.Time // ixtiyoriy
}

func (d Deps) validate() error {
	var missing []string
	if d.Orders == nil {
		missing = append(missing, "Orders")
	}
	if d.Payments == nil {
		missing = append(missing, "Payments")
	}
	if d.Notifier == nil {
		missing = append(missing, "Notifier")
	}
	if len(missing) > 0 {
		return errors.New("bog'liqlik berilmagan: " + strings.Join(missing, ", "))
	}
	return nil
}

type Checkout struct{ d Deps }

func NewCheckout(d Deps) (*Checkout, error) {
	if err := d.validate(); err != nil {
		return nil, err
	}
	if d.Now == nil {
		d.Now = time.Now // ixtiyoriy maydon uchun default
	}
	return &Checkout{d: d}, nil
}

