	if err := c.d.Payments.Charge(sum); err != nil {
		return err
	}
	if err := c.d.Orders.Save(id); err != nil {
		return err
	}
	c.d.Notifier.Notify(fmt.Sprintf("%s buyurtma %s da qabul qilindi", id, c.d.Now().Format("15:04")))
	return nil
}

