var ErrNotFound = errors.New("topilmadi")

type Task struct {
	ID    int
	Title string
	Tags  []string
}

// MemoryTasks — TaskRepo portining xotiradagi adapteri.
type MemoryTasks struct {
	mu     sync.RWMutex
	nextID int
	items  map[int]Task
}

func NewMemoryTasks() *MemoryTasks { return &MemoryTasks{items: map[int]Task{}} }

func (m *MemoryTasks) Create(_ context.Context, t Task) (Task, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.nextID++
	t.ID = m.nextID
	t.Tags = slices.Clone(t.Tags) // chaqiruvchining slice'ini saqlab qolmaymiz
	m.items[t.ID] = t
	return t, nil
}

func (m *MemoryTasks) Get(_ context.Context, id int) (Task, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	t, ok := m.items[id]
	if !ok {
		return Task{}, fmt.Errorf("task %d: %w", id, ErrNotFound)
	}
	t.Tags = slices.Clone(t.Tags) // ichki holatni tashqariga bermaymiz
	return t, nil
}

func main() {
	ctx := context.Background()
	repo := NewMemoryTasks()

	tags := []string{"ish"}
	t, _ := repo.Create(ctx, Task{Title: "Reja", Tags: tags})
	tags[0] = "O'ZGARDI" // tashqaridagi o'zgarish omborga ta'sir qilmaydi

	got, _ := repo.Get(ctx, t.ID)
	fmt.Println(got.ID, got.Title, got.Tags)

