var (
	ErrNotFound = errors.New("topilmadi")
	ErrConflict = errors.New("ziddiyat")
	ErrInvalid  = errors.New("noto'g'ri ma'lumot")
)

type Account struct {
	ID      string
	Balance int
}

// AccountRepo — service paketida e'lon qilingan port.
type AccountRepo interface {
	Get(ctx context.Context, id string) (Account, error)
	Save(ctx context.Context, a Account) error
}

type TransferService struct{ repo AccountRepo }

func NewTransferService(r AccountRepo) *TransferService { return &TransferService{repo: r} }

func (s *TransferService) Transfer(ctx context.Context, from, to string, sum int) error {
	if sum <= 0 {
		return fmt.Errorf("summa %d: %w", sum, ErrInvalid)
	}
	a, err := s.repo.Get(ctx, from)
	if err != nil {
		return fmt.Errorf("transfer: %w", err)
	}
	b, err := s.repo.Get(ctx, to)
	if err != nil {
		return fmt.Errorf("transfer: %w", err)
	}
	if a.Balance < sum {
		return fmt.Errorf("balans yetarli emas (%d < %d): %w", a.Balance, sum, ErrConflict)
	}
	a.Balance -= sum
	b.Balance += sum
	if err := s.repo.Save(ctx, a); err != nil {
		return err
	}
	return s.repo.Save(ctx, b)
}

type memRepo map[string]Account

func (m memRepo) Get(_ context.Context, id string) (Account, error) {
	a, ok := m[id]
	if !ok {
		return Account{}, fmt.Errorf("hisob %q: %w", id, ErrNotFound)
	}
	return a, nil
}

func (m memRepo) Save(_ context.Context, a Account) error {
	m[a.ID] = a
	return nil
}

func main() {
	ctx := context.Background()
	repo := memRepo{"A": {"A", 100}, "B": {"B", 20}}
	svc := NewTransferService(repo)

	err := svc.Transfer(ctx, "A", "B", 30)
	fmt.Println(err, repo["A"].Balance, repo["B"].Balance)
	fmt.Println(svc.Transfer(ctx, "B", "A", 500))
	fmt.Println(svc.Transfer(ctx, "A", "X", 10))
	fmt.Println(svc.Transfer(ctx, "A", "B", -5))
}

