type NoteService struct{ notes []Note }

func (s *NoteService) Add(text string) (Note, error) {
	if strings.TrimSpace(text) == "" {
		return Note{}, ErrEmpty
	}
	n := Note{ID: len(s.notes) + 1, Text: text}
	s.notes = append(s.notes, n)
	return n, nil
}

// NoteHandler — HTTP qatlami: JSON'ni o'qiydi, service'ni chaqiradi, javob yozadi.
