var ErrNotFound = errors.New("mahsulot topilmadi")

type Product struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

type memRepo struct { // 1. repository qatlami
	mu    sync.Mutex
	items []Product
}

func (r *memRepo) Add(_ context.Context, p Product) Product {
	r.mu.Lock()
	defer r.mu.Unlock()
	p.ID = len(r.items) + 1
	r.items = append(r.items, p)
	return p
}

func (r *memRepo) ByID(_ context.Context, id int) (Product, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if id < 1 || id > len(r.items) {
		return Product{}, ErrNotFound
	}
	return r.items[id-1], nil
}

type Catalog struct{ repo *memRepo } // 2. service qatlami

func (c Catalog) Get(ctx context.Context, id int) (Product, error) { return c.repo.ByID(ctx, id) }
func (c Catalog) Add(ctx context.Context, p Product) Product       { return c.repo.Add(ctx, p) }

func routes(c Catalog) http.Handler { // 3. handler qatlami
	mux := http.NewServeMux()
	mux.HandleFunc("POST /products", func(w http.ResponseWriter, r *http.Request) {
		var in Product
		json.NewDecoder(r.Body).Decode(&in)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(c.Add(r.Context(), in))
	})
	mux.HandleFunc("GET /products/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, _ := strconv.Atoi(r.PathValue("id"))
		if p, err := c.Get(r.Context(), id); errors.Is(err, ErrNotFound) {
			http.Error(w, err.Error(), http.StatusNotFound)
		} else {
			json.NewEncoder(w).Encode(p)
		}
	})
	return mux
}

func main() {
	srv := httptest.NewServer(routes(Catalog{repo: &memRepo{}}))
	defer srv.Close()
	show := func(resp *http.Response, _ error) {
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%s %s -> %d %s", resp.Request.Method, resp.Request.URL.Path, resp.StatusCode, b)
	}
	show(srv.Client().Post(srv.URL+"/products", "application/json", strings.NewReader(`{"name":"Choynak"}`)))
	show(srv.Client().Get(srv.URL + "/products/1"))
	show(srv.Client().Get(srv.URL + "/products/7"))
}

