package main

import (
	"errors"
	"fmt"
	"net/http"
)

// domen xatolari (domen paketida)
var (
	ErrNotFound     = errors.New("topilmadi")
	ErrConflict     = errors.New("ziddiyat")
	ErrForbidden    = errors.New("ruxsat yo'q")
	ErrUnauthorized = errors.New("autentifikatsiya kerak")
)

type ValidationError struct{ Field, Reason string }

func (e *ValidationError) Error() string { return e.Field + ": " + e.Reason }

// httpStatus — xatoni status kodga aylantiradigan YAGONA joy (HTTP adapterida).
func httpStatus(err error) int {
	var ve *ValidationError
	switch {
	case err == nil:
		return http.StatusOK
	case errors.As(err, &ve):
		return http.StatusUnprocessableEntity
	case errors.Is(err, ErrNotFound):
		return http.StatusNotFound
	case errors.Is(err, ErrConflict):
		return http.StatusConflict
	case errors.Is(err, ErrForbidden):
		return http.StatusForbidden
	case errors.Is(err, ErrUnauthorized):
		return http.StatusUnauthorized
	default:
		return http.StatusInternalServerError
	}
}

func main() {
	// Service va repository xatoni kontekst bilan o'raydi — moslash baribir ishlaydi.
	errs := []error{
		nil,
		fmt.Errorf("order.Get id=5: repo: %w", ErrNotFound),
		fmt.Errorf("user.Register: %w", ErrConflict),
		fmt.Errorf("invoice.Pay: %w", &ValidationError{"amount", "musbat bo'lsin"}),
		fmt.Errorf("doc.Delete: %w", ErrForbidden),
		errors.Join(ErrUnauthorized, errors.New("token muddati o'tgan")),
		errors.New("pq: connection reset"),
	}
	for _, err := range errs {
		code := httpStatus(err)
		fmt.Printf("%d %-21s <- %q\n", code, http.StatusText(code), fmt.Sprint(err))
	}
}

