var ErrEmailTaken = errors.New("email band")

// --- drayver (tashqi kutubxona taqlidi) ---
type PgError struct {
	Code       string
	Constraint string
}

func (e *PgError) Error() string { return "pg: " + e.Code + " " + e.Constraint }

type fakeDB struct{ emails map[string]bool }

func (db *fakeDB) Exec(email string) error {
	if db.emails[email] {
		return &PgError{Code: "23505", Constraint: "users_email_key"}
	}
	db.emails[email] = true
	return nil
}

// --- adapter: drayver xatosini domen tiliga tarjima qiladi ---
type PgUsers struct{ db *fakeDB }

func (r PgUsers) Insert(_ context.Context, email string) error {
	err := r.db.Exec(email)
	var pgErr *PgError
	if errors.As(err, &pgErr) && pgErr.Code == "23505" && pgErr.Constraint == "users_email_key" {
		return fmt.Errorf("users.Insert %s: %w", email, ErrEmailTaken)
	}
	if err != nil {
		return fmt.Errorf("users.Insert: %w", err)
	}
	return nil
}

// --- service: faqat domen xatosini biladi, pg kodlarini emas ---
type UserInserter interface {
	Insert(ctx context.Context, email string) error
}

type Signup struct{ users UserInserter }

func (s Signup) Register(ctx context.Context, email string) string {
	err := s.users.Insert(ctx, email)
	switch {
	case errors.Is(err, ErrEmailTaken):
		return "bu email bilan ro'yxatdan o'tilgan"
	case err != nil:
		return "xato: " + err.Error()
	}
	return "xush kelibsiz, " + email
}

func main() {
	ctx := context.Background()
	svc := Signup{users: PgUsers{db: &fakeDB{emails: map[string]bool{}}}}
