func (s Service) Search(ctx context.Context, q string) ([]string, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second) // service o'z chegarasini qo'shadi
	defer cancel()
	return s.repo.Find(ctx, q)
}

type Handler struct{ svc Service }

func (h Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	res, err := h.svc.Search(r.Context(), r.URL.Query().Get("q")) // r.Context() — zanjir boshi
	if err != nil {
		http.Error(w, err.Error(), http.StatusServiceUnavailable)
		return
	}
	fmt.Fprintln(w, res)
}

func main() {
	h := Handler{svc: Service{}}

	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/search?q=kitob", nil))
	fmt.Print(rec.Code, " ", rec.Body.String())

	// mijoz uzilgan so'rovni taqlid qilamiz
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	rec = httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest("GET", "/search?q=kitob", nil).WithContext(ctx))
	fmt.Print(rec.Code, " ", rec.Body.String())
}

