import (
	"context"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
)

type ctxKey struct{}

func WithRequestID(ctx context.Context, id string) context.Context {
	return context.WithValue(ctx, ctxKey{}, id)
}

// ctxHandler — har bir yozuvga kontekstdagi request_id ni qo'shadi.
type ctxHandler struct{ slog.Handler }

func (h ctxHandler) Handle(ctx context.Context, r slog.Record) error {
	if id, ok := ctx.Value(ctxKey{}).(string); ok {
		r.AddAttrs(slog.String("request_id", id))
	}
	return h.Handler.Handle(ctx, r)
}

type Repo struct{ log *slog.Logger }

func (r Repo) Save(ctx context.Context, item string) {
	r.log.InfoContext(ctx, "saqlandi", "layer", "repo", "item", item)
}

type Service struct {
	repo Repo
	log  *slog.Logger
}

func (s Service) Add(ctx context.Context, item string) {
	s.log.InfoContext(ctx, "qo'shilmoqda", "layer", "service")
	s.repo.Save(ctx, item)
}

func main() {
	base := slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{
		ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey && len(groups) == 0 {
				return slog.Attr{}
			}
			return a
		},
	})
	log := slog.New(ctxHandler{base}) // composition root: bitta logger hammaga

	svc := Service{repo: Repo{log: log}, log: log}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /items", func(w http.ResponseWriter, r *http.Request) {
		svc.Add(r.Context(), r.URL.Query().Get("name"))
	})
	requestID := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := WithRequestID(r.Context(), r.Header.Get("X-Request-ID"))
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}

	req := httptest.NewRequest("POST", "/items?name=lampa", nil)
	req.Header.Set("X-Request-ID", "req-7f3a")
	requestID(mux).ServeHTTP(httptest.NewRecorder(), req)
}

