import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"
)

type StatsRepo interface {
	Stats(ctx context.Context) (int, error)
}

type fastRepo struct{}

func (fastRepo) Stats(context.Context) (int, error) { return 128, nil }

// slowRepo — javob bermayotgan bazaga taqlid: faqat ctx tugashini kutadi.
type slowRepo struct{}

func (slowRepo) Stats(ctx context.Context) (int, error) {
	<-ctx.Done()
	return 0, fmt.Errorf("repo.Stats: %w", ctx.Err())
}

func statsHandler(repo StatsRepo, timeout time.Duration) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx, cancel := context.WithTimeout(r.Context(), timeout)
		defer cancel()
		n, err := repo.Stats(ctx)
		switch {
		case errors.Is(err, context.DeadlineExceeded):
			http.Error(w, "baza javob bermadi", http.StatusGatewayTimeout)
		case errors.Is(err, context.Canceled):
			// mijoz ketib qolgan — javob yozishning ma'nosi yo'q
		case err != nil:
			http.Error(w, "ichki xato", http.StatusInternalServerError)
		default:
			fmt.Fprintf(w, "foydalanuvchilar: %d\n", n)
		}
	}
}

func main() {
	for _, repo := range []StatsRepo{fastRepo{}, slowRepo{}} {
		rec := httptest.NewRecorder()
		statsHandler(repo, 20*time.Millisecond).ServeHTTP(rec, httptest.NewRequest("GET", "/stats", nil))
		fmt.Printf("%T: %d %s", repo, rec.Code, rec.Body.String())
	}
}

