package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
)

var (
	ErrUnauthenticated = errors.New("kirish talab qilinadi")
	ErrForbidden       = errors.New("ruxsat yo'q")
)

type Actor struct {
	ID    int
	Admin bool
}

type actorKey struct{}

func WithActor(ctx context.Context, a Actor) context.Context {
	return context.WithValue(ctx, actorKey{}, a)
}

func ActorFrom(ctx context.Context) (Actor, bool) {
	a, ok := ctx.Value(actorKey{}).(Actor)
	return a, ok
}

type Doc struct{ ID, Owner int }

// service: kim nima qila olishi — biznes qoidasi, shuning uchun shu yerda
type DocService struct{ docs map[int]Doc }

func (s DocService) Delete(ctx context.Context, id int) error {
	a, ok := ActorFrom(ctx)
	if !ok {
		return ErrUnauthenticated
	}
	if d := s.docs[id]; d.Owner != a.ID && !a.Admin {
		return fmt.Errorf("doc %d: %w", id, ErrForbidden)
	}
	delete(s.docs, id)
	return nil
}

func main() {
	svc := DocService{docs: map[int]Doc{1: {1, 10}, 2: {2, 20}}}
	mux := http.NewServeMux()
	mux.HandleFunc("DELETE /docs/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, _ := strconv.Atoi(r.PathValue("id"))
		err := svc.Delete(r.Context(), id)
		switch {
		case errors.Is(err, ErrUnauthenticated):
			w.WriteHeader(http.StatusUnauthorized)
		case errors.Is(err, ErrForbidden):
			w.WriteHeader(http.StatusForbidden)
		default:
			w.WriteHeader(http.StatusNoContent)
		}
	})
	// auth middleware o'rnida: actor'ni kontekstga qo'yamiz
	call := func(path string, a *Actor) {
		req := httptest.NewRequest("DELETE", path, nil)
		if a != nil {
			req = req.WithContext(WithActor(req.Context(), *a))
		}
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		fmt.Println(path, rec.Code)
	}
	call("/docs/1", nil)
	call("/docs/2", &Actor{ID: 10})
	call("/docs/1", &Actor{ID: 10})
	call("/docs/2", &Actor{ID: 99, Admin: true})
	fmt.Println("qolgan hujjatlar:", len(svc.docs))
}

package main

import (
	"context"
	"errors"
	"fmt"
)

var (
	ErrNotFound = errors.New("topilmadi")
	ErrUsed     = errors.New("kupon ishlatilgan")
)

type Coupon struct {
	Code    string
	Percent int
	Used    bool
}

type CouponRepo interface {
	Get(ctx context.Context, code string) (Coupon, error)
	MarkUsed(ctx context.Context, code string) error
}

type Pricing struct{ coupons CouponRepo }

func (p Pricing) Apply(ctx context.Context, price int, code string) (int, error) {
	c, err := p.coupons.Get(ctx, code)
	if err != nil {
		return price, fmt.Errorf("kupon %q: %w", code, err)
	}
	if c.Used {
		return price, ErrUsed
	}
	if err := p.coupons.MarkUsed(ctx, code); err != nil {
		return price, err
	}
	return price * (100 - c.Percent) / 100, nil
}

// fakeCoupons — test uchun xotiradagi soddalashtirilgan amalga oshirish.
type fakeCoupons map[string]Coupon

func (f fakeCoupons) Get(_ context.Context, code string) (Coupon, error) {
	c, ok := f[code]
	if !ok {
		return Coupon{}, ErrNotFound
	}
	return c, nil
}

func (f fakeCoupons) MarkUsed(_ context.Context, code string) error {
	c := f[code]
	c.Used = true
	f[code] = c
	return nil
}

func main() {
	tests := []struct {
		name    string
		code    string
		want    int
		wantErr error
	}{
		{"20% chegirma", "SALE20", 80_000, nil},
		{"takroriy ishlatish", "SALE20", 100_000, ErrUsed},
		{"noma'lum kupon", "NOPE", 100_000, ErrNotFound},
	}
	p := Pricing{coupons: fakeCoupons{"SALE20": {Code: "SALE20", Percent: 20}}}
	for _, tt := range tests {
		got, err := p.Apply(context.Background(), 100_000, tt.code)
		status := "PASS"
		if got != tt.want || !errors.Is(err, tt.wantErr) {
			status = "FAIL"
		}
		fmt.Printf("--- %s: %s (got=%d, err=%v)\n", status, tt.name, got, err)
	}
}

