package main

import (
	"context"
	"errors"
	"fmt"
	"strings"
)

var ErrNotFound = errors.New("topilmadi")

type KV interface { // port: har bir adapter shu shartnomani bajarishi kerak
	Put(ctx context.Context, k, v string) error
	Get(ctx context.Context, k string) (string, error)
}

type mapKV map[string]string // 1-adapter: map

func (m mapKV) Put(_ context.Context, k, v string) error {
	m[k] = v
	return nil
}

func (m mapKV) Get(_ context.Context, k string) (string, error) {
	if v, ok := m[k]; ok {
		return v, nil
	}
	return "", ErrNotFound
}

type logKV struct{ lines []string } // 2-adapter: jurnal, oxirgi yozuv yutadi

func (s *logKV) Put(_ context.Context, k, v string) error {
	s.lines = append(s.lines, k+"="+v)
	return nil
}

func (s *logKV) Get(_ context.Context, k string) (string, error) {
	for i := len(s.lines) - 1; i >= 0; i-- {
		if key, val, _ := strings.Cut(s.lines[i], "="); key == k {
			return val, nil
		}
	}
	return "", ErrNotFound
}

// 3-adapter: xatoli — mavjud kalitni qayta yozmaydi, "yo'q" ni xato demaydi
type buggyKV map[string]string

func (b buggyKV) Put(_ context.Context, k, v string) error {
	if _, ok := b[k]; !ok {
		b[k] = v
	}
	return nil
}

func (b buggyKV) Get(_ context.Context, k string) (string, error) { return b[k], nil }

func contract(kv KV) (fails []string) { // har qanday KV adapteri o'tishi shart
	ctx := context.Background()
	kv.Put(ctx, "til", "go")
	kv.Put(ctx, "til", "go 1.27")
	if v, _ := kv.Get(ctx, "til"); v != "go 1.27" {
		fails = append(fails, fmt.Sprintf("qayta yozish: %q", v))
	}
	if _, err := kv.Get(ctx, "yo'q"); !errors.Is(err, ErrNotFound) {
		fails = append(fails, fmt.Sprintf("ErrNotFound kutilgan, keldi: %v", err))
	}
	return fails
}

func main() {
	for _, kv := range []KV{mapKV{}, &logKV{}, buggyKV{}} {
		if fails := contract(kv); len(fails) > 0 {
			fmt.Printf("--- FAIL: %T %q\n", kv, fails)
		} else {
			fmt.Printf("--- PASS: %T\n", kv)
		}
	}
}

