package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
)

// Yadro: faqat biznes mantiq, kim chaqirayotganini bilmaydi.
type Converter struct{ rate int } // 1 USD = rate so'm

func (c Converter) ToSum(usd int) (int, error) {
	if usd < 0 {
		return 0, fmt.Errorf("manfiy summa: %d", usd)
	}
	return usd * c.rate, nil
}

// Driving adapter #1: HTTP
func httpAdapter(c Converter) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		usd, err := strconv.Atoi(r.URL.Query().Get("usd"))
		if err != nil {
			http.Error(w, "usd son bo'lsin", http.StatusBadRequest)
			return
		}
		sum, err := c.ToSum(usd)
		if err != nil {
			http.Error(w, err.Error(), http.StatusUnprocessableEntity)
			return
		}
		fmt.Fprintf(w, "%d so'm\n", sum)
	}
}

// Driving adapter #2: CLI — natija va exit kodi
func cliAdapter(c Converter, args []string) (string, int) {
	if len(args) != 1 {
		return "foydalanish: convert <usd>", 2
	}
	usd, err := strconv.Atoi(args[0])
	if err != nil {
		return "son kiriting", 2
	}
	sum, err := c.ToSum(usd)
	if err != nil {
		return err.Error(), 1
	}
	return strconv.Itoa(sum) + " so'm", 0
}

func main() {
	core := Converter{rate: 12_650}

	for _, q := range []string{"20", "-3"} {
		rec := httptest.NewRecorder()
		httpAdapter(core)(rec, httptest.NewRequest("GET", "/convert?usd="+q, nil))
		fmt.Print("HTTP usd=", q, ": ", rec.Code, " ", rec.Body.String())
	}
	for _, args := range [][]string{{"20"}, {"-3"}, {}} {
		out, code := cliAdapter(core, args)
		fmt.Printf("CLI %v: %s (exit %d)\n", args, out, code)
	}
}

package main

import (
	"context"
	"fmt"
	"io"
	"os"
)

// Port: yadro faqat shuni biladi.
type Notifier interface {
	Notify(ctx context.Context, to, text string) error
}

// Driven adapterlar
type consoleNotifier struct{ w io.Writer }

func (c consoleNotifier) Notify(_ context.Context, to, text string) error {
	_, err := fmt.Fprintf(c.w, "[console] %s: %s\n", to, text)
	return err
}

type smsNotifier struct{ sender string }

func (s smsNotifier) Notify(_ context.Context, to, text string) error {
	fmt.Printf("[sms:%s] %s ga %d belgi yuborildi\n", s.sender, to, len([]rune(text)))
	return nil
}

// multiNotifier — bir nechta adapterni bitta port ortiga yashiradi.
type multiNotifier []Notifier

func (m multiNotifier) Notify(ctx context.Context, to, text string) error {
	for _, n := range m {
		if err := n.Notify(ctx, to, text); err != nil {
			return err
		}
	}
	return nil
}

// composition root: konfiguratsiyaga qarab adapter tanlanadi
func newNotifier(kind string) (Notifier, error) {
	switch kind {
	case "console":
		return consoleNotifier{w: os.Stdout}, nil
	case "sms":
		return smsNotifier{sender: "SHOP"}, nil
	case "both":
		return multiNotifier{consoleNotifier{w: os.Stdout}, smsNotifier{sender: "SHOP"}}, nil
	}
	return nil, fmt.Errorf("noma'lum NOTIFIER=%q", kind)
}

// yadro
type Orders struct{ notify Notifier }

func (o Orders) Ship(ctx context.Context, phone string, id int) error {
	return o.notify.Notify(ctx, phone, fmt.Sprintf("Buyurtma #%d yo'lda", id))
}

func main() {
	for _, kind := range []string{"console", "sms", "both", "pigeon"} {
		n, err := newNotifier(kind) // odatda os.Getenv("NOTIFIER") dan
		if err != nil {
			fmt.Println("ishga tushmadi:", err)
			continue
		}
		Orders{notify: n}.Ship(context.Background(), "+998901234567", 42)
	}
}

