import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"
)

// RatesClient — tashqi valyuta kursi API'si uchun driven adapter.
type RatesClient struct {
	baseURL string
	http    *http.Client
}

// Manzil va klient tashqaridan beriladi — http.DefaultClient ga yashirin tayanish yo'q.
func NewRatesClient(baseURL string, hc *http.Client) *RatesClient {
	return &RatesClient{baseURL: baseURL, http: hc}
}

func (c *RatesClient) Rate(ctx context.Context, code string) (float64, error) {
	req, err := http.NewRequestWithContext(ctx, "GET", c.baseURL+"/rates/"+code, nil)
	if err != nil {
		return 0, err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return 0, fmt.Errorf("rates: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return 0, fmt.Errorf("rates: %s uchun status %d", code, resp.StatusCode)
	}
	var out struct {
		Rate float64 `json:"rate"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return 0, fmt.Errorf("rates: javob buzuq: %w", err)
	}
	return out.Rate, nil
}

func main() {
