import (
	"context"
	"fmt"
	"slices"
	"sync"
)

type Article struct {
	ID    int
	Title string
	Views int
}

// Ikki kichik port: o'quvchi va yozuvchi tomonlar uchun alohida.
type ArticleReader interface {
	Top(ctx context.Context, n int) ([]Article, error)
}

type ArticleWriter interface {
	AddView(ctx context.Context, id int) error
}

// Bitta adapter ikkala portni ham bajaradi.
type memArticles struct {
	mu   sync.Mutex
	rows map[int]*Article
}

func (m *memArticles) Top(_ context.Context, n int) ([]Article, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	var out []Article
	for _, a := range m.rows {
		out = append(out, *a)
	}
	slices.SortFunc(out, func(a, b Article) int { return b.Views - a.Views })
	return out[:min(n, len(out))], nil
}

func (m *memArticles) AddView(_ context.Context, id int) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	a, ok := m.rows[id]
	if !ok {
		return fmt.Errorf("maqola %d topilmadi", id)
	}
	a.Views++
	return nil
}

// Service'lar faqat o'ziga kerakli tomonni ko'radi.
type Tracker struct{ w ArticleWriter }  // yozadi, o'qiy olmaydi
type Homepage struct{ r ArticleReader } // o'qiydi, o'zgartira olmaydi

func (t Tracker) Visit(ctx context.Context, id int) error { return t.w.AddView(ctx, id) }

func (h Homepage) Render(ctx context.Context) {
	top, _ := h.r.Top(ctx, 2)
	for i, a := range top {
		fmt.Printf("%d. %s (%d)\n", i+1, a.Title, a.Views)
	}
}

func main() {
	store := &memArticles{rows: map[int]*Article{
		1: {1, "Go'da DI", 0}, 2: {2, "Hexagonal", 0}, 3: {3, "Clean code", 0},
	}}
	// composition root: bitta obyekt — ikki xil port sifatida
	tracker, home := Tracker{w: store}, Homepage{r: store}

	ctx := context.Background()
	for _, id := range []int{2, 3, 2, 2, 3, 1} {
		tracker.Visit(ctx, id)
	}
	fmt.Println(tracker.Visit(ctx, 9))
	home.Render(ctx)
}

