import (
	"context"
	"fmt"
	"maps"
)

// Repos — tranzaksiya ichida ishlatiladigan amallar.
type Repos interface {
	Debit(acc string, sum int) error
	Credit(acc string, sum int) error
}

// TxRunner — port: "shu funksiyani bitta tranzaksiyada bajar".
type TxRunner interface {
	WithinTx(ctx context.Context, fn func(ctx context.Context, r Repos) error) error
}

// memDB — in-memory adapter: nusxada ishlaydi, xato bo'lsa nusxani tashlaydi.
type memDB struct{ balances map[string]int }

type memTx struct{ b map[string]int }

func (t *memTx) Debit(acc string, sum int) error {
	if t.b[acc] < sum {
		return fmt.Errorf("%s: mablag' yetarli emas", acc)
	}
	t.b[acc] -= sum
	return nil
}

func (t *memTx) Credit(acc string, sum int) error {
	if _, ok := t.b[acc]; !ok {
		return fmt.Errorf("%s: hisob yo'q", acc)
	}
	t.b[acc] += sum
	return nil
}

func (db *memDB) WithinTx(ctx context.Context, fn func(context.Context, Repos) error) error {
	tx := &memTx{b: maps.Clone(db.balances)} // BEGIN
	if err := fn(ctx, tx); err != nil {
		return fmt.Errorf("rollback: %w", err) // ROLLBACK: nusxa tashlanadi
	}
	db.balances = tx.b // COMMIT
	return nil
}

// Service tranzaksiya CHEGARASINI belgilaydi, lekin SQL'ni bilmaydi.
type Transfers struct{ tx TxRunner }

func (s Transfers) Move(ctx context.Context, from, to string, sum int) error {
	return s.tx.WithinTx(ctx, func(ctx context.Context, r Repos) error {
		if err := r.Debit(from, sum); err != nil {
			return err
		}
		return r.Credit(to, sum)
	})
}

func main() {
	db := &memDB{balances: map[string]int{"ali": 100, "vali": 0}}
	svc := Transfers{tx: db}
	ctx := context.Background()

	err := svc.Move(ctx, "ali", "vali", 40)
	fmt.Println(err, db.balances)

	err = svc.Move(ctx, "ali", "nobody", 10) // Debit o'tdi, Credit yiqildi
	fmt.Println(err)
	fmt.Println("rollback'dan keyin:", db.balances)
}

