)

// OrderPlaced — domen hodisasi: "nima bo'ldi".
type OrderPlaced struct {
	OrderID int
	Email   string
	Total   int
}

// Port: yadro hodisani e'lon qiladi, kim tinglashini bilmaydi.
type Publisher interface {
	Publish(ctx context.Context, e OrderPlaced) error
}

// In-memory adapter: obunachilar ro'yxati (production'da — Kafka, NATS, outbox jadvali).
type Bus struct {
	subs []func(context.Context, OrderPlaced)
}

func (b *Bus) Subscribe(fn func(context.Context, OrderPlaced)) { b.subs = append(b.subs, fn) }

func (b *Bus) Publish(ctx context.Context, e OrderPlaced) error {
	for _, fn := range b.subs {
		fn(ctx, e)
	}
	return nil
}

type Orders struct {
	pub    Publisher
	nextID int
}

func (o *Orders) Place(ctx context.Context, email string, total int) (int, error) {
	o.nextID++
	id := o.nextID
	// ... buyurtmani saqlash ...
	if err := o.pub.Publish(ctx, OrderPlaced{OrderID: id, Email: email, Total: total}); err != nil {
		return 0, fmt.Errorf("hodisa yuborilmadi: %w", err)
	}
	return id, nil
}

func main() {
	bus := &Bus{}
	// composition root: obunachilarni ulaymiz — Orders ularni bilmaydi
	bus.Subscribe(func(_ context.Context, e OrderPlaced) {
		fmt.Printf("email: %s ga #%d tasdig'i\n", e.Email, e.OrderID)
	})
	revenue := 0
	bus.Subscribe(func(_ context.Context, e OrderPlaced) { revenue += e.Total })

	orders := &Orders{pub: bus}
	ctx := context.Background()
	orders.Place(ctx, "olim@example.com", 120_000)
	orders.Place(ctx, "zarina@example.com", 45_000)
	fmt.Println("analitika: tushum =", revenue)
}

