	"strconv"
	"time"
)

type Config struct {
	Addr        string
	DatabaseURL string
	Timeout     time.Duration
	Workers     int
}

// LoadConfig os.Getenv ni o'zi chaqirmaydi — getenv parametr sifatida keladi.
func LoadConfig(getenv func(string) string) (Config, error) {
	cfg := Config{Addr: ":8080", Timeout: 5 * time.Second, Workers: 4}
	var errs []error
	if v := getenv("ADDR"); v != "" {
		cfg.Addr = v
	}
	if cfg.DatabaseURL = getenv("DATABASE_URL"); cfg.DatabaseURL == "" {
		errs = append(errs, errors.New("DATABASE_URL majburiy"))
	}
	if v := getenv("TIMEOUT"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("TIMEOUT: %w", err))
		}
		cfg.Timeout = d
	}
	if v := getenv("WORKERS"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 {
			errs = append(errs, fmt.Errorf("WORKERS=%q musbat son bo'lsin", v))
		}
		cfg.Workers = n
	}
	return cfg, errors.Join(errs...) // barcha xatolar birdan
}

func env(m map[string]string) func(string) string {
	return func(k string) string { return m[k] }
}

func main() {
	// main'da: cfg, err := LoadConfig(os.Getenv)
	cfg, err := LoadConfig(env(map[string]string{"DATABASE_URL": "postgres://app@db/app", "TIMEOUT": "2s"}))
	fmt.Printf("%+v %v\n", cfg, err)

	_, err = LoadConfig(env(map[string]string{"TIMEOUT": "ikki", "WORKERS": "0"}))
	fmt.Println(err)
}

