type MemStore struct { // driven adapter: xotiradagi saqlash
	mu sync.Mutex
	m  map[string]string
}

func NewMemStore() *MemStore { return &MemStore{m: map[string]string{}} }

func (s *MemStore) Save(_ context.Context, code, url string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.m[code] = url
	return nil
}

type LinkSaver interface { // yadro: port va service
	Save(ctx context.Context, code, url string) error
}

type Shortener struct {
	store   LinkSaver
	nextID  func() string
	baseURL string
}

func NewShortener(store LinkSaver, nextID func() string, baseURL string) *Shortener {
	return &Shortener{store: store, nextID: nextID, baseURL: baseURL}
}

func (s *Shortener) Shorten(ctx context.Context, url string) (string, error) {
	code := s.nextID()
	return s.baseURL + "/" + code, s.store.Save(ctx, code, url)
}

func NewHTTPHandler(s *Shortener) http.Handler { // driving adapter: HTTP
	mux := http.NewServeMux()
	mux.HandleFunc("POST /links", func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		short, err := s.Shorten(r.Context(), strings.TrimSpace(string(body)))
		if err != nil {
			http.Error(w, "ichki xato", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		fmt.Fprintln(w, short)
	})
	return mux
}

func main() { // composition root: konkret tiplar faqat shu yerda
	baseURL := "https://sh.rt" // 1. konfiguratsiya (odatda env'dan)
	store := NewMemStore()     // 2. driven adapter (keyinroq: postgres)
	n := 0
	ids := func() string {
		n++
		return fmt.Sprintf("k%d", n)
	}
	svc := NewShortener(store, ids, baseURL)       // 3. yadro
	srv := httptest.NewServer(NewHTTPHandler(svc)) // 4-5. driving adapter va ishga tushirish
	defer srv.Close()

	for _, u := range []string{"https://go.dev/doc", "https://pkg.go.dev"} {
		resp, _ := srv.Client().Post(srv.URL+"/links", "text/plain", strings.NewReader(u))
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Print(resp.StatusCode, " ", string(b))
	}
	fmt.Println("saqlangan:", len(store.m))
}

