	if *name == "" {
		return errors.New("ism berilmagan: -name yoki USER_NAME")
	}
	msg := fmt.Sprintf("Salom, %s! (%s)", *name, getenv("APP_ENV"))
	if *upper {
		msg = strings.ToUpper(msg)
	}
	_, err := fmt.Fprintln(stdout, msg)
	return err
}

