import (
	"context"
	"errors"
	"fmt"
)

type Component interface {
	Name() string
	Start(ctx context.Context) error
	Stop(ctx context.Context) error
}

type comp struct {
	name    string
	failErr error
}

func (c comp) Name() string { return c.name }

func (c comp) Start(context.Context) error {
	if c.failErr != nil {
		return c.failErr
	}
	fmt.Println("  start:", c.name)
	return nil
}

func (c comp) Stop(context.Context) error {
	fmt.Println("  stop: ", c.name)
	return nil
}

// App — komponentlarni tartib bilan yoqadi va teskari tartibda o'chiradi.
type App struct {
	comps   []Component
	started []Component
}

func (a *App) Start(ctx context.Context) error {
	for _, c := range a.comps {
		if err := c.Start(ctx); err != nil {
			// yarim yoqilgan ilova qolmasin: yoqilganlarni o'chiramiz
			return errors.Join(fmt.Errorf("%s: %w", c.Name(), err), a.Stop(ctx))
		}
		a.started = append(a.started, c)
	}
	return nil
}

func (a *App) Stop(ctx context.Context) error {
	var errs []error
	for i := len(a.started) - 1; i >= 0; i-- {
		errs = append(errs, a.started[i].Stop(ctx))
	}
	a.started = nil
	return errors.Join(errs...)
}

func main() {
	ctx := context.Background()
	fmt.Println("1) normal:")
	app := &App{comps: []Component{comp{name: "db"}, comp{name: "cache"}, comp{name: "http"}}}
	app.Start(ctx)
	app.Stop(ctx)

	fmt.Println("2) http yiqildi:")
	app = &App{comps: []Component{comp{name: "db"}, comp{name: "cache"}, comp{name: "http", failErr: errors.New("port band")}}}
	fmt.Println("  xato:", app.Start(ctx))
}

