type Config struct{ DSN, Env string }

type DB struct{ dsn string }

type UserRepo struct{ db *DB }

type UserService struct {
	repo *UserRepo
	log  *slog.Logger
}

type Server struct{ users *UserService }

// Provider'lar: har biri faqat o'z bog'liqliklarini parametr qilib oladi.
func ProvideConfig() Config { return Config{DSN: "postgres://localhost/app", Env: "dev"} }

func ProvideDB(c Config) (*DB, func(), error) {
	if !strings.HasPrefix(c.DSN, "postgres://") {
		return nil, nil, fmt.Errorf("DSN noto'g'ri: %q", c.DSN)
	}
	fmt.Println("db ochildi")
	return &DB{dsn: c.DSN}, func() { fmt.Println("db yopildi") }, nil
}

func ProvideLogger(c Config) *slog.Logger { return slog.New(slog.DiscardHandler) }

func ProvideUserRepo(db *DB) *UserRepo { return &UserRepo{db: db} }

func ProvideUserService(r *UserRepo, l *slog.Logger) *UserService {
	return &UserService{repo: r, log: l}
}

func ProvideServer(u *UserService) *Server { return &Server{users: u} }

// InitializeServer — "injector": provider'larni to'g'ri tartibda chaqiradi.
// google/wire aynan shunday kodni avtomatik generatsiya qiladi.
func InitializeServer() (*Server, func(), error) {
	cfg := ProvideConfig()
	db, cleanup, err := ProvideDB(cfg)
	if err != nil {
		return nil, nil, err
	}
	logger := ProvideLogger(cfg)
	repo := ProvideUserRepo(db)
	users := ProvideUserService(repo, logger)
	return ProvideServer(users), cleanup, nil
}

func main() {
	srv, cleanup, err := InitializeServer()
	if err != nil {
		fmt.Println(err)
		return
	}
	defer cleanup()
	fmt.Println("server tayyor, dsn =", srv.users.repo.db.dsn)
}

package main

import (
	"fmt"
	"reflect"
)

// Container — tip bo'yicha konstruktorlarni saqlaydi (dig/fx g'oyasi, juda soddalashtirilgan).
type Container struct {
	providers map[reflect.Type]reflect.Value
	built     map[reflect.Type]reflect.Value
}

func NewContainer() *Container {
	return &Container{providers: map[reflect.Type]reflect.Value{}, built: map[reflect.Type]reflect.Value{}}
}

// Provide: fn — func(A, B, ...) T ko'rinishidagi konstruktor.
func (c *Container) Provide(fn any) {
	v := reflect.ValueOf(fn)
	c.providers[v.Type().Out(0)] = v
}

// args — fn parametrlarini konteynerdan yig'adi (rekursiv).
func (c *Container) args(fn reflect.Value) ([]reflect.Value, error) {
	in := make([]reflect.Value, fn.Type().NumIn())
	for i := range in {
		t := fn.Type().In(i)
		if v, ok := c.built[t]; ok {
			in[i] = v
			continue
		}
		p, ok := c.providers[t]
		if !ok {
			return nil, fmt.Errorf("%v uchun provider yo'q", t)
		}
		pargs, err := c.args(p)
		if err != nil {
			return nil, fmt.Errorf("%v <- %w", t, err)
		}
		in[i] = p.Call(pargs)[0]
		c.built[t] = in[i] // bitta nusxa (singleton)
	}
	return in, nil
}

// Invoke: fn ni bog'liqliklari bilan chaqiradi.
func (c *Container) Invoke(fn any) error {
	v := reflect.ValueOf(fn)
	in, err := c.args(v)
	if err != nil {
		return err
	}
	v.Call(in)
	return nil
}

type Config struct{ DSN string }
type DB struct{ DSN string }
type Mailer struct{}
type Service struct {
	db   *DB
	mail *Mailer
}

func main() {
	c := NewContainer()
	c.Provide(func() *Config { return &Config{DSN: "mem://"} })
	c.Provide(func(cfg *Config) *DB { return &DB{DSN: cfg.DSN} })
	c.Provide(func(db *DB, m *Mailer) *Service { return &Service{db: db, mail: m} })

	// Mailer provider'i unutildi — kompilyator jim, xato faqat ishga tushganda:
	err := c.Invoke(func(s *Service) { fmt.Println("service tayyor") })
	fmt.Println("xato:", err)

	c.Provide(func() *Mailer { return &Mailer{} })
	err = c.Invoke(func(s *Service) { fmt.Println("service tayyor, dsn =", s.db.DSN) })
	fmt.Println("xato:", err)
}

