import (
	"fmt"
	"go/parser"
	"go/token"
	"maps"
	"path"
	"slices"
	"strconv"
	"strings"
)

// Qoida: qaysi qatlam nimani import qila OLMAYDI.
var forbidden = map[string][]string{
	"internal/order":    {"net/http", "database/sql", "example.com/shop/internal/"},
	"internal/postgres": {"net/http", "example.com/shop/internal/httpapi"},
	"internal/httpapi":  {"database/sql", "example.com/shop/internal/postgres"},
}

// Tekshiriladigan fayllar (haqiqiy asbobda — diskdan o'qiladi).
var files = map[string]string{
	"internal/order/service.go": `package order
import ("context"; "errors"; "net/http")`,
	"internal/postgres/orders.go": `package postgres
import ("database/sql"; "example.com/shop/internal/order")`,
	"internal/httpapi/orders.go": `package httpapi
import ("net/http"; "example.com/shop/internal/order"; "example.com/shop/internal/postgres")`,
}

func main() {
	fset := token.NewFileSet()
	violations := 0
	for _, name := range slices.Sorted(maps.Keys(files)) {
		f, err := parser.ParseFile(fset, name, files[name], parser.ImportsOnly)
		if err != nil {
			fmt.Println(err)
			continue
		}
		for _, imp := range f.Imports {
			p, _ := strconv.Unquote(imp.Path.Value)
			for _, bad := range forbidden[path.Dir(name)] {
				// "x/" bilan tugagan qoida — prefiks, qolgani — aniq nom
				if p == bad || (strings.HasSuffix(bad, "/") && strings.HasPrefix(p, bad)) {
					fmt.Printf("%s: %q import qilinmasin\n", name, p)
					violations++
				}
			}
		}
	}
