// NewServer lifecycle hook'larini ro'yxatdan o'tkazadi: fx ularni to'g'ri tartibda chaqiradi.
func NewServer(lc fx.Lifecycle, cfg Config, mux *http.ServeMux) *http.Server {
	srv := &http.Server{Addr: cfg.Addr, Handler: mux}
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			ln, err := net.Listen("tcp", srv.Addr)
			if err != nil {
				return err // fx ishga tushishni to'xtatadi va oldingi OnStop'larni chaqiradi
			}
			fmt.Println("server ishga tushdi", srv.Addr)
			go srv.Serve(ln)
			return nil
		},
		OnStop: func(ctx context.Context) error {
			fmt.Println("server to'xtatilmoqda")
			return srv.Shutdown(ctx)
		},
	})
	return srv
}

func main() {
	fx.New(
		fx.NopLogger, // fx'ning o'z log'larini o'chiramiz
		fx.Provide(NewConfig, NewMux, NewServer),
		fx.Invoke(func(*http.Server) {}), // server'ni "so'raymiz" — aks holda u yaratilmaydi
	).Run() // OnStart'lar, keyin SIGINT/SIGTERM kutiladi, so'ng OnStop'lar
