package memory

import (
	"context"
	"sync"

	"example.com/todoapp/internal/todo" // adapter yadroni import qiladi, aksincha emas
)

type Todos struct {
	mu   sync.Mutex
	rows []todo.Todo
}

func (m *Todos) Insert(_ context.Context, t todo.Todo) (todo.Todo, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	t.ID = len(m.rows) + 1
	m.rows = append(m.rows, t)
	return t, nil
}

func (m *Todos) Get(_ context.Context, id int) (todo.Todo, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if id < 1 || id > len(m.rows) {
		return todo.Todo{}, todo.ErrNotFound
	}
	return m.rows[id-1], nil
}

