package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"

	"example.com/todoapp/internal/todo"
)

// todoService — handler'ga kerakli metodlar; *todo.Service ularni bajaradi.
type todoService interface {
	Create(ctx context.Context, title string) (todo.Todo, error)
	Get(ctx context.Context, id int) (todo.Todo, error)
}

type todoJSON struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
}

func New(svc todoService) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /todos", func(w http.ResponseWriter, r *http.Request) {
		var in todoJSON
		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
			http.Error(w, "buzuq JSON", http.StatusBadRequest)
			return
		}
		t, err := svc.Create(r.Context(), in.Title)
		reply(w, http.StatusCreated, t, err)
	})
	mux.HandleFunc("GET /todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, _ := strconv.Atoi(r.PathValue("id"))
		t, err := svc.Get(r.Context(), id)
		reply(w, http.StatusOK, t, err)
	})
	return mux
}

func reply(w http.ResponseWriter, ok int, t todo.Todo, err error) {
	switch {
	case errors.Is(err, todo.ErrInvalid):
		http.Error(w, err.Error(), http.StatusUnprocessableEntity)
	case errors.Is(err, todo.ErrNotFound):
		http.Error(w, err.Error(), http.StatusNotFound)
	case err != nil:
		http.Error(w, "ichki xato", http.StatusInternalServerError)
	default:
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(ok)
		json.NewEncoder(w).Encode(todoJSON{ID: t.ID, Title: t.Title})
	}
}

