// classify buyruq satridagi har bir bo'lakning turini aniqlaydi.
// valueFlags — qiymatni keyingi bo'lakda oladigan flag'lar (masalan, -p 2).
func classify(args []string, valueFlags map[string]bool) {
	afterDash := false
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case afterDash:
			fmt.Printf("%-16s pozitsion (-- dan keyin)\n", a)
		case a == "--":
			fmt.Printf("%-16s flag'lar tugadi\n", a)
			afterDash = true
		case strings.HasPrefix(a, "-") && a != "-":
			name := strings.TrimLeft(a, "-")
			if k, v, ok := strings.Cut(name, "="); ok {
				fmt.Printf("%-16s flag %q = %q\n", a, k, v)
			} else if valueFlags[name] && i+1 < len(args) {
				i++
				fmt.Printf("%-16s flag %q = %q\n", a+" "+args[i], name, args[i])
			} else {
				fmt.Printf("%-16s bool flag %q\n", a, name)
			}
		case i == 0:
			fmt.Printf("%-16s subcommand\n", a)
		default:
			fmt.Printf("%-16s pozitsion\n", a)
		}
	}
}

func main() {
	// $ todo add -p 2 --due=friday -v "Hisobot yozish" -- -eslatma
	args := []string{"add", "-p", "2", "--due=friday", "-v", "Hisobot yozish", "--", "-eslatma"}
	classify(args, map[string]bool{"p": true})
}

