// parsePrices narxlarni stdout'ga, ogohlantirishlarni stderr'ga yozadi.
func parsePrices(input []string, stdout, stderr io.Writer) {
	for i, s := range input {
		n, err := strconv.Atoi(s)
		if err != nil {
			fmt.Fprintf(stderr, "ogohlantirish: %d-qator %q son emas, o'tkazildi\n", i+1, s)
			continue
		}
		fmt.Fprintln(stdout, n)
	}
}

func main() {
	input := []string{"300", "abc", "120", "", "250"}

	// Terminal: ikkala oqim ham ekranga chiqadi.
	var screen bytes.Buffer
	parsePrices(input, &screen, &screen)
	fmt.Print("$ prices\n", screen.String())

	// Pipe: "prices | sort -n" — keyingi dasturga faqat stdout boradi.
	var stdout, stderr bytes.Buffer
	parsePrices(input, &stdout, &stderr)
	nums := strings.Fields(stdout.String())
	slices.SortFunc(nums, func(a, b string) int {
		x, _ := strconv.Atoi(a)
		y, _ := strconv.Atoi(b)
		return x - y
	})
	fmt.Println("\n$ prices | sort -n")
	fmt.Print(stderr.String()) // stderr pipe'ga kirmaydi, ekranda qoladi
	fmt.Println(strings.Join(nums, "\n"))
}

