// ExitError xato bilan birga chiqish kodini ham olib yuradi.
type ExitError struct {
	Code int
	Err  error
}

func (e *ExitError) Error() string { return e.Err.Error() }
func (e *ExitError) Unwrap() error { return e.Err }

func withCode(code int, format string, a ...any) error {
	return &ExitError{Code: code, Err: fmt.Errorf(format, a...)}
}

// exitCode: nil — 0, ExitError — o'z kodi, boshqa har qanday xato — 1.
func exitCode(err error) int {
	if err == nil {
		return 0
	}
	var ee *ExitError
	if errors.As(err, &ee) { // o'ralgan (%w) bo'lsa ham topiladi
		return ee.Code
	}
	return 1
}

func main() {
	errs := []error{
		nil,
		os.ErrNotExist,
		withCode(2, "noto'g'ri argument: %q", "-x"),
		fmt.Errorf("sync: %w", withCode(69, "server javob bermadi")),
	}
	for _, err := range errs {
		fmt.Printf("kod=%-3d xato=%v\n", exitCode(err), err)
	}
}

