type usageError struct{ msg string }

func (e usageError) Error() string { return e.msg }

func run(args []string, stdout io.Writer) error {
	fs := flag.NewFlagSet("square", flag.ContinueOnError)
	fs.SetOutput(io.Discard) // flag xabarlarini o'zimiz boshqaramiz
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprintln(stdout, "foydalanish: square <son>")
			return err
		}
		return usageError{err.Error()}
	}
	if fs.NArg() != 1 {
		return usageError{"aniq bitta son kerak"}
	}
	n, err := strconv.Atoi(fs.Arg(0))
	if err != nil {
		return fmt.Errorf("son emas: %q", fs.Arg(0))
	}
	fmt.Fprintln(stdout, n*n)
	return nil
}

