	var ue usageError
	switch {
	case err == nil, errors.Is(err, flag.ErrHelp):
		return 0 // yordam so'rash — xato emas
	case errors.As(err, &ue):
		return 2 // noto'g'ri foydalanish
	default:
		return 1 // ish vaqtidagi xato
	}
}

