			return nil
		}},
	}
}

// usage yordam matnini jadvaldan avtomatik yasaydi — yangi buyruq qo'shilsa, o'zi chiqadi.
func usage(out io.Writer, cmds []command) {
	fmt.Fprintln(out, "foydalanish: tool <buyruq> [argumentlar]\n\nbuyruqlar:")
	for _, c := range cmds {
		fmt.Fprintf(out, "  %-8s %s\n", c.name, c.summary)
