// newFlagSet har bir buyruq uchun alohida FlagSet va yordam matnini tayyorlaydi.
func newFlagSet(name string, out io.Writer) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(out)
	switch name {
	case "add":
		fs.String("title", "", "vazifa nomi")
		fs.Int("p", 1, "muhimlik (1-3)")
	case "list":
		fs.Bool("all", false, "bajarilganlarni ham ko'rsatish")
	default:
		return nil
	}
	fs.Usage = func() {
		fmt.Fprintf(out, "foydalanish: todo %s [flag'lar]\n", name)
		fs.PrintDefaults()
	}
	return fs
}

func run(args []string, out io.Writer) error {
	if len(args) == 2 && args[0] == "help" { // "todo help add" == "todo add -h"
		args = []string{args[1], "-h"}
	}
	fs := newFlagSet(args[0], out)
	if fs == nil {
		return fmt.Errorf("noma'lum buyruq %q", args[0])
	}
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}
	fmt.Fprintf(out, "%s:", fs.Name())
	fs.VisitAll(func(f *flag.Flag) { fmt.Fprintf(out, " %s=%s", f.Name, f.Value) })
	fmt.Fprintln(out)
	return nil
}

func main() {
	for _, args := range [][]string{{"help", "add"}, {"list", "-h"}, {"add", "-title", "Hisobot", "-p", "3"}} {
		fmt.Println("$ todo", strings.Join(args, " "))
		if err := run(args, os.Stdout); err != nil && !errors.Is(err, flag.ErrHelp) {
			fmt.Println("xato:", err)
		}
	}
}

