import "fmt"

// distance — Levenshtein masofasi: bir so'zni ikkinchisiga aylantirish uchun nechta tahrir kerak.
func distance(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur := make([]int, len(rb)+1)
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev = cur
	}
	return prev[len(rb)]
}

// suggest eng yaqin buyruqni topadi (masofa 2 dan oshmasa).
func suggest(input string, names []string) (string, bool) {
	best, bestD := "", 3
	for _, n := range names {
		if d := distance(input, n); d < bestD {
			best, bestD = n, d
		}
	}
	return best, best != ""
}

func main() {
	names := []string{"install", "list", "remove", "status", "update"}
	for _, in := range []string{"instal", "stauts", "lst", "deploy"} {
		if s, ok := suggest(in, names); ok {
			fmt.Printf("tool: %q — noma'lum buyruq. Shuni nazarda tutdingizmi: %q?\n", in, s)
		} else {
			fmt.Printf("tool: %q — noma'lum buyruq. Ro'yxat: tool help\n", in)
		}
	}
}

