import (
	"fmt"
	"maps"
	"slices"
	"strings"
)

// node — buyruqlar daraxti tuguni: yo bolalari bor (guruh), yo o'zi bajariladi (barg).
type node struct {
	children map[string]*node
	run      func(args []string) string
}

func (n *node) exec(path, args []string) string {
	if n.run != nil {
		return n.run(args)
	}
	if len(args) == 0 || n.children[args[0]] == nil {
		names := slices.Sorted(maps.Keys(n.children))
		return fmt.Sprintf("%s: buyruqlardan birini tanlang: %s", strings.Join(path, " "), strings.Join(names, ", "))
	}
	return n.children[args[0]].exec(append(path, args[0]), args[1:])
}

func leaf(f func(args []string) string) *node { return &node{run: f} }

func main() {
	remotes := map[string]string{"origin": "https://example.com/app.git"}
	root := &node{children: map[string]*node{
		"status": leaf(func([]string) string { return "o'zgarishlar yo'q" }),
		"remote": {children: map[string]*node{
			"add": leaf(func(a []string) string {
				if len(a) != 2 {
					return "foydalanish: git remote add <nom> <url>"
				}
				remotes[a[0]] = a[1]
				return "qo'shildi: " + a[0]
			}),
			"list": leaf(func([]string) string {
				var lines []string
				for _, k := range slices.Sorted(maps.Keys(remotes)) {
					lines = append(lines, k+"  "+remotes[k])
				}
				return strings.Join(lines, "\n")
			}),
		}},
	}}
	for _, line := range []string{"remote add backup https://example.com/b.git", "remote list", "remote", "status", ""} {
		fmt.Printf("$ git %s\n%s\n", line, root.exec([]string{"git"}, strings.Fields(line)))
	}
}

