	"strings"
)

// globals — har bir buyruqda ishlaydigan umumiy flag'lar (cobra'dagi PersistentFlags kabi).
type globals struct {
	verbose bool
	config  string
}

// register umumiy flag'larni istalgan FlagSet'ga ulaydi.
// Diqqat: XxxVar o'zgaruvchiga standart qiymatni YOZADI, shuning uchun joriy qiymatni standart qilib beramiz.
func (g *globals) register(fs *flag.FlagSet) {
	fs.BoolVar(&g.verbose, "v", g.verbose, "batafsil chiqish")
	fs.StringVar(&g.config, "config", g.config, "konfiguratsiya fayli")
}

func run(args []string) {
	g := globals{config: "app.json"}
	root := flag.NewFlagSet("app", flag.ContinueOnError)
	g.register(root)
	root.Parse(args) // buyruqdan OLDINGI global flag'lar
	rest := root.Args()
	if len(rest) == 0 {
		fmt.Println("buyruq kerak")
		return
	}
	sub := flag.NewFlagSet(rest[0], flag.ContinueOnError)
	g.register(sub) // o'sha o'zgaruvchilar — buyruqdan KEYIN ham ishlaydi
	force := sub.Bool("force", false, "majburan")
	sub.Parse(rest[1:])
	fmt.Printf("%-38s → v=%t config=%s force=%t args=%v\n",
		strings.Join(args, " "), g.verbose, g.config, *force, sub.Args())
}

func main() {
	run([]string{"-v", "deploy", "prod"})
	run([]string{"deploy", "-v", "-config=prod.json", "prod"})
	run([]string{"-config=a.json", "deploy", "-force", "prod"})
	run([]string{"-v", "-config=a.json", "deploy", "-v=false", "prod"})
}

