	"slices"
)

// parseInterspersed flag'lar va pozitsion argumentlar aralash kelsa ham hammasini o'qiydi.
func parseInterspersed(fs *flag.FlagSet, args []string) ([]string, error) {
	var tail []string
	if i := slices.Index(args, "--"); i >= 0 { // "--" dan keyingisi doim pozitsion
		args, tail = args[:i], args[i+1:]
	}
	var positional []string
	for {
		if err := fs.Parse(args); err != nil {
			return nil, err
		}
		rest := fs.Args()
		if len(rest) == 0 {
			return append(positional, tail...), nil
		}
		positional = append(positional, rest[0]) // flag emas — saqlaymiz va davom etamiz
		args = rest[1:]
	}
}

func main() {
	args := []string{"a.txt", "-v", "b.txt", "-o", "out", "c.txt", "--", "-d.txt"}

	std := flag.NewFlagSet("cp", flag.ContinueOnError)
	v1 := std.Bool("v", false, "")
	o1 := std.String("o", "", "")
	std.Parse(args)
	fmt.Printf("flag.Parse:        v=%t o=%q args=%q\n", *v1, *o1, std.Args())

	fs := flag.NewFlagSet("cp", flag.ContinueOnError)
	v2 := fs.Bool("v", false, "")
	o2 := fs.String("o", "", "")
	pos, err := parseInterspersed(fs, args)
	fmt.Printf("parseInterspersed: v=%t o=%q args=%q err=%v\n", *v2, *o2, pos, err)
}

