// enumValue — faqat ruxsat etilgan qiymatlardan birini qabul qiladigan flag.Value.
type enumValue struct {
	allowed []string
	value   string
}

func newEnum(def string, allowed ...string) *enumValue {
	return &enumValue{allowed: allowed, value: def}
}

func (e *enumValue) String() string { return e.value }

func (e *enumValue) Set(s string) error {
	if !slices.Contains(e.allowed, s) {
		return fmt.Errorf("ruxsat etilgan qiymatlar: %s", strings.Join(e.allowed, ", "))
	}
	e.value = s
	return nil
}

func main() {
	for _, args := range [][]string{{}, {"-format=json"}, {"-format", "yaml"}, {"-level=debug", "-format=csv"}} {
		fs := flag.NewFlagSet("report", flag.ContinueOnError)
		fs.SetOutput(io.Discard)
		format := newEnum("table", "table", "json", "csv")
		level := newEnum("info", "debug", "info", "warn", "error")
		fs.Var(format, "format", "chiqish formati: table|json|csv")
		fs.Var(level, "level", "log darajasi")

		line := strings.Join(args, " ")
		if line == "" {
			line = "(flag'siz)"
		}
		if err := fs.Parse(args); err != nil {
			fmt.Printf("%-25s xato: %v\n", line, err)
			continue
		}
		fmt.Printf("%-25s format=%s level=%s\n", line, format, level)
	}
}

