import (
	"flag"
	"fmt"
	"strings"
)

// expandShort "-vvv" ni "-v -v -v" ga yoyadi: flag paketi birlashgan qisqa flag'larni bilmaydi.
func expandShort(args []string) []string {
	var out []string
	for _, a := range args {
		if len(a) > 2 && a[0] == '-' && a[1] != '-' && strings.Trim(a[1:], "v") == "" {
			for range len(a) - 1 {
				out = append(out, "-v")
			}
			continue
		}
		out = append(out, a)
	}
	return out
}

func parse(args []string) (verbosity int, quiet bool) {
	fs := flag.NewFlagSet("app", flag.ContinueOnError)
	fs.BoolFunc("v", "batafsillikni 1 ga oshiradi (takrorlash mumkin)", func(string) error {
		verbosity++ // har bir -v uchun alohida chaqiriladi
		return nil
	})
	fs.BoolVar(&quiet, "q", false, "faqat xatolar")
	fs.Parse(expandShort(args))
	return verbosity, quiet
}

func main() {
	levels := []string{"WARN", "INFO", "DEBUG", "TRACE"}
	for _, args := range [][]string{{}, {"-v"}, {"-v", "-v"}, {"-vvv"}, {"-q"}} {
		n, q := parse(args)
		level := levels[min(n, len(levels)-1)]
		if q {
			level = "ERROR"
		}
		fmt.Printf("%-7q verbosity=%d → %s\n", strings.Join(args, " "), n, level)
	}
}

