func validate(args []string) error {
	fs := flag.NewFlagSet("export", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Bool("json", false, "JSON formatida")
	fs.Bool("csv", false, "CSV formatida")
	fs.String("out", "", "chiqish fayli")
	fs.Bool("stdout", false, "stdout'ga yozish")
	if err := fs.Parse(args); err != nil {
		return err
	}
	set := map[string]bool{}
	fs.Visit(func(f *flag.Flag) { set[f.Name] = true }) // faqat aniq berilgan flag'lar
	var errs []error
	if set["json"] && set["csv"] {
		errs = append(errs, errors.New("-json va -csv birga ishlatilmaydi"))
	}
	if set["out"] == set["stdout"] { // ikkalasi ham yo'q yoki ikkalasi ham bor
		errs = append(errs, errors.New("-out yoki -stdout dan aynan bittasi kerak"))
	}
	return errors.Join(errs...) // xato bo'lmasa nil
}

