import (
	"fmt"
	"slices"
	"strings"
)

// argsFunc — pozitsion argumentlarni tekshiruvchi (cobra'dagi Args maydoni kabi).
type argsFunc func(args []string) error

func exactArgs(n int) argsFunc {
	return func(args []string) error {
		if len(args) != n {
			return fmt.Errorf("aniq %d ta argument kerak, %d ta berildi", n, len(args))
		}
		return nil
	}
}

func minArgs(n int) argsFunc {
	return func(args []string) error {
		if len(args) < n {
			return fmt.Errorf("kamida %d ta argument kerak, %d ta berildi", n, len(args))
		}
		return nil
	}
}

func oneOf(valid ...string) argsFunc {
	return func(args []string) error {
		for _, a := range args {
			if !slices.Contains(valid, a) {
				return fmt.Errorf("%q noto'g'ri; mumkin: %s", a, strings.Join(valid, ", "))
			}
		}
		return nil
	}
}

// all bir nechta tekshiruvchini ketma-ket qo'llaydi.
func all(checks ...argsFunc) argsFunc {
	return func(args []string) error {
		for _, c := range checks {
			if err := c(args); err != nil {
				return err
			}
		}
		return nil
	}
}

func main() {
	env := all(exactArgs(1), oneOf("dev", "prod"))
	cases := []struct {
		cmd   string
		check argsFunc
		args  []string
	}{
		{"rename <eski> <yangi>", exactArgs(2), []string{"a.txt"}},
		{"rm <fayl>...", minArgs(1), []string{"a.txt", "b.txt"}},
		{"rm <fayl>...", minArgs(1), nil},
		{"env <dev|prod>", env, []string{"test"}},
		{"env <dev|prod>", env, []string{"prod"}},
	}
	for _, c := range cases {
		result := "ok"
		if err := c.check(c.args); err != nil {
			result = "xato: " + err.Error()
		}
		fmt.Printf("%-22s %-14s %s\n", c.cmd, fmt.Sprint(c.args), result)
	}
}

