// usage flag'larni ikki ustunli jadval qilib, standart qiymatlari bilan chiqaradi.
func usage(fs *flag.FlagSet, w io.Writer) {
	fmt.Fprintf(w, "Foydalanish: %s [flag'lar] <papka>\n\nFlag'lar:\n", fs.Name())
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fs.VisitAll(func(f *flag.Flag) {
		name, text := flag.UnquoteUsage(f)
		left := "  --" + f.Name
		if name != "" {
			left += " <" + name + ">"
		}
		if f.DefValue != "" && f.DefValue != "false" && f.DefValue != "0" {
			text += " (standart: " + f.DefValue + ")"
		}
		fmt.Fprintf(tw, "%s\t%s\n", left, text)
	})
	tw.Flush()
	fmt.Fprint(w, "\nMisollar:\n  sync --dry-run ./photos\n  sync --workers 8 --exclude '*.tmp' ./docs\n")
}

func main() {
	fs := flag.NewFlagSet("sync", flag.ContinueOnError)
	fs.Bool("dry-run", false, "hech narsani o'zgartirmay, rejani ko'rsatish")
	fs.Int("workers", 4, "parallel ishchilar soni")
	fs.String("exclude", "", "o'tkazib yuboriladigan `naqsh`")
	fs.Duration("timeout", 30*time.Second, "bitta fayl uchun maksimal vaqt")
	fs.SetOutput(os.Stdout)
	fs.Usage = func() { usage(fs, fs.Output()) }

	err := fs.Parse([]string{"--help"})
	fmt.Println("\nParse natijasi:", err)
}

