import (
	"flag"
	"fmt"
	"io"
	"strings"
)

// bindEnv aniq berilmagan har bir flag uchun PREFIX_NOM muhit o'zgaruvchisini qo'llaydi.
// Natija: flag > muhit > standart.
func bindEnv(fs *flag.FlagSet, prefix string, lookup func(string) (string, bool)) error {
	set := map[string]bool{}
	fs.Visit(func(f *flag.Flag) { set[f.Name] = true })
	var err error
	fs.VisitAll(func(f *flag.Flag) {
		if set[f.Name] || err != nil {
			return
		}
		key := prefix + "_" + strings.ToUpper(strings.ReplaceAll(f.Name, "-", "_"))
		if v, ok := lookup(key); ok {
			if e := fs.Set(f.Name, v); e != nil { // Set qiymatni flag.Value orqali tekshiradi
				err = fmt.Errorf("%s=%q: %w", key, v, e)
			}
		}
	})
	return err
}

func run(args []string, env map[string]string) {
	fs := flag.NewFlagSet("srv", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	port := fs.Int("port", 8080, "port")
	level := fs.String("log-level", "info", "log darajasi")
	workers := fs.Int("workers", 4, "ishchilar soni")
	fs.Parse(args)
	lookup := func(k string) (string, bool) { // haqiqiy dasturda: os.LookupEnv
		v, ok := env[k]
		return v, ok
	}
	if err := bindEnv(fs, "APP", lookup); err != nil {
		fmt.Println("xato:", err)
		return
	}
	fmt.Printf("port=%d log-level=%s workers=%d\n", *port, *level, *workers)
}

func main() {
	env := map[string]string{"APP_PORT": "9000", "APP_LOG_LEVEL": "debug"}
	run(nil, env)
	run([]string{"-port=7000"}, env)
	run(nil, map[string]string{"APP_WORKERS": "ko'p"})
}

