import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type Config struct {
	Host  string
	Port  int
	Debug bool
}

// load qatlamlarni pastdan yuqoriga qo'llaydi: standart → fayl → muhit → flag.
func load(args []string, env map[string]string, file io.Reader) (Config, map[string]string, error) {
	cfg := Config{Host: "localhost", Port: 8080}
	src := map[string]string{"host": "standart", "port": "standart", "debug": "standart"}

	var fc struct { // pointer maydonlar — faylda kalit bor-yo'qligini bilish uchun
		Host  *string `json:"host"`
		Port  *int    `json:"port"`
		Debug *bool   `json:"debug"`
	}
	if err := json.NewDecoder(file).Decode(&fc); err != nil {
		return cfg, nil, fmt.Errorf("config fayl: %w", err)
	}
	if fc.Host != nil {
		cfg.Host, src["host"] = *fc.Host, "fayl"
	}
	if fc.Port != nil {
		cfg.Port, src["port"] = *fc.Port, "fayl"
	}
	if fc.Debug != nil {
		cfg.Debug, src["debug"] = *fc.Debug, "fayl"
	}

	if v, ok := env["APP_PORT"]; ok {
		p, err := strconv.Atoi(v)
		if err != nil {
			return cfg, nil, fmt.Errorf("APP_PORT: %w", err)
		}
		cfg.Port, src["port"] = p, "muhit"
	}

	fs := flag.NewFlagSet("srv", flag.ContinueOnError)
	fs.StringVar(&cfg.Host, "host", cfg.Host, "server manzili") // joriy qiymat — flag standarti
	fs.IntVar(&cfg.Port, "port", cfg.Port, "port")
	fs.BoolVar(&cfg.Debug, "debug", cfg.Debug, "debug rejimi")
	if err := fs.Parse(args); err != nil {
		return cfg, nil, err
	}
	fs.Visit(func(f *flag.Flag) { src[f.Name] = "flag" })
	return cfg, src, nil
}

func main() {
	file := strings.NewReader(`{"host": "example.com", "port": 8000}`)
	env := map[string]string{"APP_PORT": "9000"}
	cfg, src, err := load([]string{"-debug"}, env, file)
	if err != nil {
		fmt.Println("xato:", err)
		return
	}
	fmt.Printf("host  = %-12s (%s)\n", cfg.Host, src["host"])
	fmt.Printf("port  = %-12d (%s)\n", cfg.Port, src["port"])
	fmt.Printf("debug = %-12t (%s)\n", cfg.Debug, src["debug"])

	_, _, err = load(nil, map[string]string{"APP_PORT": "abc"}, strings.NewReader("{}"))
	fmt.Println("xato:", err)
}

