// openInput: "-" yoki bo'sh nom — stdin, aks holda fayl.
// fs.FS parametri tufayli namunada diskka tegmaymiz (dasturda: os.Open yoki os.DirFS(".")).
func openInput(fsys fs.FS, name string, stdin io.Reader) (io.ReadCloser, error) {
	if name == "" || name == "-" {
		return io.NopCloser(stdin), nil // stdin'ni biz yopmaymiz
	}
	f, err := fsys.Open(name)
	if err != nil {
		return nil, err
	}
	return f, nil
}

