		r, err := openInput(fsys, name, stdin)
		if err != nil {
			fmt.Printf("%-10s xato: %v\n", name, err)
			continue
		}
		data, _ := io.ReadAll(r)
		r.Close()
		fmt.Printf("%-10s %q\n", name, data)
	}
}

