// cat har bir faylni chiqaradi; xato bo'lsa stderr'ga yozib, KEYINGISIGA o'tadi.
// Birorta xato bo'lgan bo'lsa, oxirida kod 1 qaytadi (GNU cat ham shunday).
func cat(fsys fs.FS, names []string, stdout, stderr io.Writer) int {
	code := 0
	for _, name := range names {
		if err := copyFile(fsys, name, stdout); err != nil {
			fmt.Fprintf(stderr, "cat: %v\n", err)
			code = 1
		}
	}
	return code
}

func copyFile(fsys fs.FS, name string, w io.Writer) error {
	f, err := fsys.Open(name)
	if err != nil {
		return err
	}
	defer f.Close() // alohida funksiyada — sikl ichida defer to'planib qolmaydi
	_, err = io.Copy(w, f)
	return err
}

func main() {
	fsys := fstest.MapFS{
		"a.txt":      {Data: []byte("birinchi\n")},
		"b.txt":      {Data: []byte("ikkinchi\n")},
		"logs/x.log": {Data: []byte("...")},
	}
	var out, errOut bytes.Buffer
	code := cat(fsys, []string{"a.txt", "yoq.txt", "logs", "b.txt"}, &out, &errOut)
	fmt.Printf("stdout:\n%sstderr:\n%skod: %d\n", out.String(), errOut.String(), code)
}

