	"fmt"
	"io"
	"os"
	"strings"
)

// uniqC ketma-ket takrorlangan qatorlarni sanaydi (uniq -c kabi).
func uniqC(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	out := bufio.NewWriter(w) // ko'p kichik yozuv o'rniga — kam system call
	prev, count := "", 0
	emit := func() {
		if count > 0 {
			fmt.Fprintf(out, "%7d %s\n", count, prev)
		}
	}
	for sc.Scan() {
		if line := sc.Text(); line == prev && count > 0 {
			count++
		} else {
			emit()
			prev, count = line, 1
		}
	}
	emit()
	if err := sc.Err(); err != nil {
		return err
	}
	return out.Flush() // Flush xatosi ham xato (masalan, disk to'lgan)
}

func main() {
	// $ uniq -c < access.log — bu yerda stdin o'rnida strings.Reader
	input := "GET /\nGET /\nGET /api\nPOST /login\nPOST /login\nPOST /login\nGET /\n"
	if err := uniqC(strings.NewReader(input), os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "uniq:", err)
		os.Exit(1)
	}
}

