// isTerminal: belgili qurilma (character device) bo'lsa — terminal deb hisoblaymiz.
// Haqiqiy dasturda: fi, err := os.Stdin.Stat(); ok := err == nil && isTerminal(fi)
func isTerminal(fi fs.FileInfo) bool {
	return fi.Mode()&os.ModeCharDevice != 0
}

func describe(fi fs.FileInfo) string {
	switch m := fi.Mode(); {
	case isTerminal(fi):
		return "terminal — foydalanuvchidan so'rash mumkin"
	case m&os.ModeNamedPipe != 0:
		return "pipe — cat data.txt | tool"
	case m.IsRegular():
		return "fayl — tool < data.txt"
	default:
		return "boshqa"
	}
}

