// confirm savol beradi va ha/yo'q javobini kutadi; bo'sh javob — standart qiymat.
func confirm(in *bufio.Scanner, out io.Writer, question string, def bool) (bool, error) {
	hint := "[y/N]"
	if def {
		hint = "[Y/n]"
	}
	for {
		fmt.Fprintf(out, "%s %s ", question, hint)
		if !in.Scan() {
			if err := in.Err(); err != nil {
				return false, err
			}
			return false, io.ErrUnexpectedEOF // stdin yopildi (Ctrl+D yoki bo'sh pipe)
		}
		switch strings.ToLower(strings.TrimSpace(in.Text())) {
		case "":
			return def, nil
		case "y", "yes", "ha":
			return true, nil
		case "n", "no", "yo'q":
			return false, nil
		}
		fmt.Fprintln(out, "iltimos, y yoki n kiriting")
	}
}

func main() {
	for _, input := range []string{"\n", "Y\n", "balki\nha\n", ""} {
		var screen bytes.Buffer
		in := bufio.NewScanner(strings.NewReader(input))
		ok, err := confirm(in, &screen, "O'chirilsinmi?", false)
		fmt.Printf("kirish=%-14q javob=%-5t err=%v\n  ekran: %q\n", input, ok, err, screen.String())
	}
}

