// prompter savollarni beradi. echo — faqat namoyish uchun: haqiqiy terminal yozilganni o'zi ko'rsatadi.
type prompter struct {
	in   *bufio.Scanner
	out  io.Writer
	echo bool
}

// ask: bo'sh javob — def; validate xato qaytarsa, savol qayta beriladi.
func (p *prompter) ask(q, def string, validate func(string) error) (string, error) {
	for {
		fmt.Fprintf(p.out, "%s [%s]: ", q, def)
		if !p.in.Scan() {
			return "", io.ErrUnexpectedEOF
		}
		ans := strings.TrimSpace(p.in.Text())
		if p.echo {
			fmt.Fprintln(p.out, ans)
		}
		if ans == "" {
			ans = def
		}
		if validate == nil {
			return ans, nil
		}
		if err := validate(ans); err != nil {
			fmt.Fprintln(p.out, "  ✖", err)
			continue
		}
		return ans, nil
	}
}

func validPort(s string) error {
	if n, err := strconv.Atoi(s); err != nil || n < 1 || n > 65535 {
		return fmt.Errorf("port 1..65535 oralig'idagi son bo'lishi kerak")
	}
	return nil
}

func main() {
	// $ app init  — foydalanuvchi: Enter, "80800", "8080"
	p := &prompter{in: bufio.NewScanner(strings.NewReader("\n80800\n8080\n")), out: os.Stdout, echo: true}
	name, _ := p.ask("Loyiha nomi", "myapp", nil)
	port, err := p.ask("Port", "3000", validPort)
	if err != nil {
		fmt.Println("xato:", err)
		return
	}
	fmt.Printf("\nyaratildi: %s.json {name: %s, port: %s}\n", name, name, port)
}

