// cleanup fayllarni o'chiradi: --dry-run faqat rejani ko'rsatadi, --yes tasdiqni o'tkazib yuboradi.
func cleanup(files []string, o options, ask func(q string) bool, out io.Writer) error {
	if o.dryRun {
		for _, f := range files {
			fmt.Fprintln(out, "[dry-run] o'chirilardi:", f)
		}
		return nil
	}
	if !o.yes {
