// useColor: --color flag'i > NO_COLOR > TERM=dumb > stdout terminalmi.
func useColor(mode string, getenv func(string) string, isTTY bool) bool {
	switch mode {
	case "always":
		return true
	case "never":
		return false
	}
	if getenv("NO_COLOR") != "" { // no-color.org: o'rnatilgan va bo'sh bo'lmasa — rangsiz
		return false
	}
	if getenv("TERM") == "dumb" {
		return false
	}
	return isTTY // auto: faqat terminalda; pipe va faylga escape kodlar yozilmasin
}

func env(kv ...string) func(string) string {
	m := map[string]string{}
	for i := 0; i+1 < len(kv); i += 2 {
		m[kv[i]] = kv[i+1]
	}
	return func(k string) string { return m[k] }
}

func main() {
	cases := []struct {
		desc  string
		mode  string
		get   func(string) string
		isTTY bool
	}{
		{"terminal", "auto", env(), true},
		{"pipe: tool | less", "auto", env(), false},
		{"NO_COLOR=1", "auto", env("NO_COLOR", "1"), true},
		{"NO_COLOR= (bo'sh)", "auto", env("NO_COLOR", ""), true},
		{"TERM=dumb", "auto", env("TERM", "dumb"), true},
		{"--color=always | less", "always", env("NO_COLOR", "1"), false},
		{"--color=never", "never", env(), true},
	}
	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "HOLAT\tRANG")
