)

// bar progress satrini chizadi: [######......]  50% 2/4
func bar(done, total, width int) string {
	filled := done * width / total
	return fmt.Sprintf("[%s%s] %3d%% %d/%d",
		strings.Repeat("#", filled), strings.Repeat(".", width-filled), done*100/total, done, total)
}

// screen terminalni taqlid qiladi: \r kursorni qator boshiga qaytaradi, keyingi matn ustidan yoziladi.
func screen(s string) string {
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		if j := strings.LastIndex(line, "\r"); j >= 0 {
			lines[i] = line[j+1:]
		}
	}
	return strings.Join(lines, "\n")
}

func main() {
	var out strings.Builder
	for i := 0; i <= 4; i++ {
		fmt.Fprintf(&out, "\r%s", bar(i, 4, 12)) // har kadr oldingisining ustiga
	}
	out.WriteString("\n") // oxirida yangi qator — keyingi chiqish alohida qatordan boshlansin

	frame := len(bar(0, 4, 12)) + 1 // kadrlar uzunligi bir xil (%3d) — qoldiq qolmaydi
	fmt.Printf("yuborilgan bayt: %d\n", out.Len())
	fmt.Printf("dastlabki 2 kadr: %q\n", out.String()[:2*frame])
	fmt.Printf("ekranda: %s", screen(out.String()))
}

