import (
	"fmt"
	"io"
	"os"
	"strings"
)

// progress terminalda bitta qatorni yangilaydi, aks holda (CI log, fayl) har 25% da qator yozadi.
type progress struct {
	w     io.Writer // odatda os.Stderr — stdout'dagi ma'lumot buzilmasin
	tty   bool
	total int
	step  int // oxirgi chop etilgan 25% bosqichi
}

func (p *progress) Update(done int) {
	pct := done * 100 / p.total
	if p.tty {
		fmt.Fprintf(p.w, "\r%3d%% (%d/%d)", pct, done, p.total)
		if done == p.total {
			fmt.Fprintln(p.w)
		}
		return
	}
	if s := pct / 25; s > p.step {
		p.step = s
		fmt.Fprintf(p.w, "progress: %d%% (%d/%d)\n", pct, done, p.total)
	}
}

func main() {
	var tty strings.Builder
	p := &progress{w: &tty, tty: true, total: 8}
	for i := 1; i <= 8; i++ {
		p.Update(i)
	}
	fmt.Printf("TTY: %q\n\nTTY emas:\n", tty.String())

	p = &progress{w: os.Stdout, total: 8}
	for i := 1; i <= 8; i++ {
		p.Update(i)
	}
}

