type Service struct {
	Name   string `json:"name"`
	Status string `json:"status"`
	Port   int    `json:"port"`
}

// render bitta ma'lumotni turli formatda chiqaradi: odam uchun — table, skript uchun — json/name.
func render(w io.Writer, format string, items []Service) error {
	switch format {
	case "table":
		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "NAME\tSTATUS\tPORT")
		for _, s := range items {
			fmt.Fprintf(tw, "%s\t%s\t%d\n", s.Name, s.Status, s.Port)
		}
		return tw.Flush()
	case "json":
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		return enc.Encode(items)
	case "name": // kubectl get -o name kabi: har qatorda bitta nom
		for _, s := range items {
			fmt.Fprintln(w, s.Name)
		}
		return nil
	default:
		return fmt.Errorf("noma'lum format %q (table|json|name)", format)
	}
}

func main() {
	items := []Service{{"api", "running", 8080}, {"worker", "stopped", 0}}
	for _, f := range []string{"table", "json", "name", "yaml"} {
		fmt.Println("$ svc list -o", f)
		if err := render(os.Stdout, f, items); err != nil {
			fmt.Println("xato:", err)
		}
	}
}

