func newLogger(w io.Writer, verbose bool) *slog.Logger {
	level := slog.LevelWarn // CLI odatda jim: faqat muammolar
	if verbose {
		level = slog.LevelDebug
	}
	return slog.New(slog.NewTextHandler(w, &slog.HandlerOptions{
		Level: level,
		ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey && len(groups) == 0 {
				return slog.Attr{} // vaqtni olib tashlaymiz: natija deterministik bo'lsin
			}
			return a
		},
	}))
}

// run ma'lumotni stdout'ga, diagnostikani (log) stderr'ga yozadi.
func run(files []string, verbose bool, stdout, stderr io.Writer) {
	log := newLogger(stderr, verbose)
	log.Debug("boshlandi", "files", len(files))
	for _, f := range files {
		if !strings.HasSuffix(f, ".txt") {
			log.Warn("o'tkazib yuborildi", "file", f, "sabab", "kengaytma .txt emas")
			continue
		}
		log.Debug("qayta ishlanmoqda", "file", f)
		fmt.Fprintln(stdout, strings.ToUpper(f))
	}
}

