import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
)

var errInterrupted = errors.New("foydalanuvchi to'xtatdi (Ctrl+C)")

// process elementlarni birma-bir bajaradi va har qadamdan oldin ctx'ni tekshiradi.
func process(ctx context.Context, items []string, afterEach func(i int)) error {
	for i, it := range items {
		if ctx.Err() != nil {
			return fmt.Errorf("%d/%d bajarildi: %w", i, len(items), context.Cause(ctx))
		}
		fmt.Println("bajarildi:", it)
		afterEach(i)
	}
	return nil
}

func main() {
	// Haqiqiy dastur: Ctrl+C (yoki SIGTERM) kelganda ctx bekor bo'ladi.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	// Namoyish: Ctrl+C ni taqlid qilamiz — 2-elementdan keyin bekor qilamiz.
	ctx, cancel := context.WithCancelCause(ctx)
	defer cancel(nil)
	err := process(ctx, []string{"a.csv", "b.csv", "c.csv", "d.csv"}, func(i int) {
		if i == 1 {
			cancel(errInterrupted)
		}
	})

	code := 0
	switch {
	case errors.Is(err, errInterrupted), errors.Is(err, context.Canceled):
		code = 130 // 128 + SIGINT(2) — shell'lardagi an'ana
	case err != nil:
		code = 1
	}
	fmt.Printf("xato: %v\nchiqish kodi: %d\n", err, code)
}

