import (
	"context"
	"errors"
	"flag"
	"fmt"
	"time"
)

// fetch sekin tarmoq so'rovini taqlid qiladi.
func fetch(ctx context.Context, d time.Duration) error {
	select {
	case <-time.After(d):
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func run(args []string) int {
	fs := flag.NewFlagSet("fetch", flag.ContinueOnError)
	timeout := fs.Duration("timeout", 5*time.Second, "maksimal kutish vaqti (0 — cheksiz)")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	ctx := context.Background()
	if *timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, *timeout)
		defer cancel()
	}
	if err := fetch(ctx, 200*time.Millisecond); err != nil {
		fmt.Printf("fetch: %v (timeout %v)\n", err, *timeout)
		if errors.Is(err, context.DeadlineExceeded) {
			return 124 // timeout(1) buyrug'i an'anasi
		}
		return 1
	}
	fmt.Println("javob olindi")
	return 0
}

func main() {
	for _, args := range [][]string{{"-timeout=1s"}, {"-timeout=50ms"}, {"-timeout=0"}} {
		fmt.Println("$ fetch", args[0])
		fmt.Println("kod:", run(args))
	}
}

