// run — sinaladigan CLI: "calc add 2 3", "calc div 6 3".
func run(args []string, stdout, stderr io.Writer) int {
	if len(args) != 3 {
		fmt.Fprintln(stderr, "foydalanish: calc <add|div> <a> <b>")
		return 2
	}
	a, err1 := strconv.Atoi(args[1])
	b, err2 := strconv.Atoi(args[2])
	if err1 != nil || err2 != nil {
		fmt.Fprintln(stderr, "calc: argumentlar butun son bo'lishi kerak")
		return 2
	}
	switch args[0] {
	case "add":
		fmt.Fprintln(stdout, a+b)
	case "div":
		if b == 0 {
			fmt.Fprintln(stderr, "calc: nolga bo'lish")
			return 1
		}
		fmt.Fprintln(stdout, a/b)
	default:
		fmt.Fprintf(stderr, "calc: noma'lum amal %q\n", args[0])
		return 2
	}
	return 0
}

func main() {
	tests := []struct {
		name     string
		args     string
		wantOut  string
		wantErr  string // stderr shu matnni o'z ichiga olishi kerak
		wantCode int
	}{
		{"add", "add 2 3", "5\n", "", 0},
		{"div", "div 7 2", "3\n", "", 0},
		{"nolga", "div 1 0", "", "nolga bo'lish", 1},
		{"argumentsiz", "", "", "foydalanish", 2},
		{"son emas", "add x 1", "", "butun son", 2},
		{"noma'lum amal", "mul 2 3", "", `"mul"`, 2},
	}
	failed := 0
	for _, tt := range tests { // _test.go da: t.Run(tt.name, func(t *testing.T) { ... })
		var out, errOut bytes.Buffer
		code := run(strings.Fields(tt.args), &out, &errOut)
		if code != tt.wantCode || out.String() != tt.wantOut || !strings.Contains(errOut.String(), tt.wantErr) {
			failed++
			fmt.Printf("--- FAIL: %s: kod=%d stdout=%q stderr=%q\n", tt.name, code, out.String(), errOut.String())
			continue
		}
		fmt.Printf("--- PASS: %s\n", tt.name)
	}
	fmt.Printf("%d/%d o'tdi\n", len(tests)-failed, len(tests))
}

