func newRootCmd() *cobra.Command {
	var env string
	root := &cobra.Command{
		Use:           "deployer",
		Short:         "Ilovani muhitlarga joylash",
		SilenceUsage:  true, // xato bo'lganda butun help chop etilmasin
		SilenceErrors: true, // xatoni main o'zi chiqaradi
		PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
			if env != "dev" && env != "prod" { // har bir subcommand'dan oldin ishlaydi
				return fmt.Errorf("--env dev yoki prod bo'lishi kerak, %q emas", env)
			}
			return nil
		},
	}
	root.PersistentFlags().StringVarP(&env, "env", "e", "dev", "muhit: dev|prod")
	root.RegisterFlagCompletionFunc("env", func(*cobra.Command, []string, string) ([]string, cobra.ShellCompDirective) {
		return []string{"dev", "prod"}, cobra.ShellCompDirectiveNoFileComp
	})

	root.AddCommand(&cobra.Command{
		Use:       "release <xizmat>",
		Short:     "Xizmatni joylaydi",
		Args:      cobra.ExactArgs(1),
		ValidArgs: []string{"api", "worker"}, // Tab bosilganda takliflar
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := cmd.Context().Err(); err != nil { // Ctrl+C bosilgan bo'lsa
				return err
			}
			fmt.Fprintf(cmd.OutOrStdout(), "%s → %s joylandi\n", args[0], env)
			return nil
		},
	})
	return root
}

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	err := newRootCmd().ExecuteContext(ctx) // ctx har bir buyruqqa cmd.Context() orqali yetadi
	stop()
	if err != nil {
		fmt.Fprintln(os.Stderr, "xato:", err)
		os.Exit(1)
	}
