type bookmark struct {
	url string
	tag string
}

type app struct {
	items []bookmark
	out   io.Writer
}

var errUsage = errors.New("noto'g'ri foydalanish")

// run bitta buyruqni bajaradi: 0 — ok, 1 — ish vaqtidagi xato, 2 — foydalanish xatosi.
func (a *app) run(args []string) int {
	cmds := map[string]func([]string) error{"add": a.add, "list": a.list}
	err := fmt.Errorf("%w: bm <add|list> ...", errUsage)
	if len(args) > 0 && cmds[args[0]] != nil {
		err = cmds[args[0]](args[1:])
	}
	if err == nil {
		return 0
	}
	fmt.Fprintln(a.out, "bm:", err)
	if errors.Is(err, errUsage) {
		return 2
	}
	return 1
}

func (a *app) add(args []string) error {
	fs := flag.NewFlagSet("add", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	tag := fs.String("tag", "umumiy", "teg")
	if err := fs.Parse(args); err != nil || fs.NArg() != 1 {
		return fmt.Errorf("%w: bm add [-tag nom] <url>", errUsage)
	}
	url := fs.Arg(0)
	if slices.ContainsFunc(a.items, func(b bookmark) bool { return b.url == url }) {
		return fmt.Errorf("%s allaqachon saqlangan", url)
	}
	a.items = append(a.items, bookmark{url, *tag})
	fmt.Fprintf(a.out, "#%d saqlandi\n", len(a.items))
	return nil
}

func (a *app) list([]string) error {
	tw := tabwriter.NewWriter(a.out, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "ID\tTEG\tURL")
	for i, b := range a.items {
		fmt.Fprintf(tw, "%d\t%s\t%s\n", i+1, b.tag, b.url)
	}
	return tw.Flush()
}

func main() {
	a := &app{out: os.Stdout} // namoyish uchun ma'lumot ham, xato ham bitta oqimga
	for _, line := range []string{
		"add -tag go https://go.dev", "add https://example.com", "list",
		"add https://go.dev", "add -tag", "rm 1",
	} {
		fmt.Println("$ bm", line)
		if code := a.run(strings.Fields(line)); code != 0 {
			fmt.Printf("(chiqish kodi %d)\n", code)
		}
	}
}

