type stat struct {
	Path  string `json:"path"`
	Count int    `json:"count"`
}

// run stdin'dan "LEVEL METHOD PATH" qatorlarini o'qib, eng ko'p uchragan yo'llarni chiqaradi.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("logstat", flag.ContinueOnError)
	fs.SetOutput(stderr)
	level := fs.String("level", "", "faqat shu darajadagi qatorlar (ERROR, WARN, ...)")
	top := fs.Int("top", 3, "nechta natija ko'rsatilsin")
	asJSON := fs.Bool("json", false, "JSON formatida chiqarish")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	counts, bad := map[string]int{}, 0
	sc := bufio.NewScanner(stdin)
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) != 3 {
			bad++
			continue
		}
		if *level == "" || strings.EqualFold(f[0], *level) {
			counts[f[2]]++
		}
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(stderr, "logstat:", err)
		return 1
	}
	if bad > 0 {
		fmt.Fprintf(stderr, "logstat: %d ta noto'g'ri qator o'tkazildi\n", bad)
	}
	stats := make([]stat, 0, len(counts))
	for p, c := range counts {
		stats = append(stats, stat{p, c})
	}
	slices.SortFunc(stats, func(a, b stat) int { // soni bo'yicha kamayish, teng bo'lsa — nom
		return cmp.Or(cmp.Compare(b.Count, a.Count), cmp.Compare(a.Path, b.Path))
	})
	stats = stats[:min(*top, len(stats))]
	if *asJSON {
		json.NewEncoder(stdout).Encode(stats)
		return 0
	}
	tw := tabwriter.NewWriter(stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "SONI\tYO'L")
	for _, s := range stats {
		fmt.Fprintf(tw, "%d\t%s\n", s.Count, s.Path)
	}
	tw.Flush()
	return 0
}

const appLog = "INFO GET /\nERROR GET /api/users\nINFO GET /api/users\nWARN POST /login\n" +
	"ERROR GET /api/users\nbuzilgan qator\nERROR POST /login\nINFO GET /\nINFO GET /about\n"

func main() {
	for _, args := range [][]string{{}, {"-level=error", "-top=1"}, {"-json", "-top=2"}, {"-top=x"}} {
