import (
	"errors"
	"fmt"
	"maps"
	"slices"
	"sync"
)

type Notifier interface {
	Notify(to, msg string) string
}

type Factory func(cfg map[string]string) (Notifier, error)

var (
	mu        sync.RWMutex
	factories = map[string]Factory{}
)

func Register(name string, f Factory) {
	mu.Lock()
	defer mu.Unlock()
	if _, dup := factories[name]; dup {
		panic("takroriy registratsiya: " + name)
	}
	factories[name] = f
}

func Providers() []string {
	mu.RLock()
	defer mu.RUnlock()
	return slices.Sorted(maps.Keys(factories))
}

func New(name string, cfg map[string]string) (Notifier, error) {
	mu.RLock()
	f, ok := factories[name]
	mu.RUnlock()
	if !ok {
		return nil, fmt.Errorf("noma'lum provayder %q (bor: %v)", name, Providers())
	}
	return f(cfg)
}

type sms struct{ sender string }
type email struct{ from string }

func (s sms) Notify(to, msg string) string   { return "SMS " + s.sender + " -> " + to + ": " + msg }
func (e email) Notify(to, msg string) string { return "EMAIL " + e.from + " -> " + to + ": " + msg }

func init() {
	Register("sms", func(cfg map[string]string) (Notifier, error) {
		return sms{sender: cfg["sender"]}, nil
	})
	Register("email", func(cfg map[string]string) (Notifier, error) {
		if cfg["from"] == "" {
			return nil, errors.New("email: from majburiy")
		}
		return email{from: cfg["from"]}, nil
	})
}

func main() {
	fmt.Println("provayderlar:", Providers())
	n, _ := New("sms", map[string]string{"sender": "SHOP"})
	fmt.Println(n.Notify("+998901234567", "buyurtma tayyor"))
	if _, err := New("email", nil); err != nil {
		fmt.Println("xato:", err)
	}
	if _, err := New("push", nil); err != nil {
		fmt.Println("xato:", err)
	}
}

