import "fmt"

type Button interface{ Render() string }
type Checkbox interface{ Render() string }

// UIFactory — bir oilaga mansub komponentlarni yaratadi
type UIFactory interface {
	Button(label string) Button
	Checkbox(label string, on bool) Checkbox
}

type lightButton struct{ label string }
type lightCheckbox struct {
	label string
	on    bool
}

func (b lightButton) Render() string { return "[ " + b.label + " ]" }
func (c lightCheckbox) Render() string {
	if c.on {
		return "[x] " + c.label
	}
	return "[ ] " + c.label
}

type darkButton struct{ label string }
type darkCheckbox struct {
	label string
	on    bool
}

func (b darkButton) Render() string { return "<< " + b.label + " >>" }
func (c darkCheckbox) Render() string {
	if c.on {
		return "(*) " + c.label
	}
	return "( ) " + c.label
}

type lightTheme struct{}
type darkTheme struct{}

func (lightTheme) Button(l string) Button              { return lightButton{l} }
func (lightTheme) Checkbox(l string, on bool) Checkbox { return lightCheckbox{l, on} }
func (darkTheme) Button(l string) Button               { return darkButton{l} }
func (darkTheme) Checkbox(l string, on bool) Checkbox  { return darkCheckbox{l, on} }

// renderForm faqat UIFactory'ni biladi
func renderForm(f UIFactory) {
	fmt.Println(f.Checkbox("Eslab qolish", true).Render())
	fmt.Println(f.Button("Kirish").Render())
}

func main() {
	fmt.Println("light:")
	renderForm(lightTheme{})
	fmt.Println("dark:")
	renderForm(darkTheme{})
