import (
	"fmt"
	"strings"
)

type QueryBuilder struct {
	table string
	where []string
	args  []any
	order string
	limit int
}

func Select(table string) *QueryBuilder { return &QueryBuilder{table: table} }

func (q *QueryBuilder) Where(cond string, arg any) *QueryBuilder {
	q.where = append(q.where, cond)
	q.args = append(q.args, arg)
	return q
}

func (q *QueryBuilder) OrderBy(col string) *QueryBuilder {
	q.order = col
	return q
}

func (q *QueryBuilder) Limit(n int) *QueryBuilder {
	q.limit = n
	return q
}

func (q *QueryBuilder) Build() (string, []any) {
	var sb strings.Builder
	sb.WriteString("SELECT * FROM " + q.table)
	if len(q.where) > 0 {
		sb.WriteString(" WHERE " + strings.Join(q.where, " AND "))
	}
	if q.order != "" {
		sb.WriteString(" ORDER BY " + q.order)
	}
	if q.limit > 0 {
		fmt.Fprintf(&sb, " LIMIT %d", q.limit)
	}
	return sb.String(), q.args
}

func main() {
	sql, args := Select("users").
		Where("age > ?", 18).
		Where("city = ?", "Toshkent").
		OrderBy("name").
		Limit(10).
		Build()
	fmt.Println(sql)
	fmt.Println(args)

	sql, _ = Select("orders").Build()
	fmt.Println(sql)
}

