import (
	"errors"
	"fmt"
	"time"
)

type Conn struct{ ID int }

type Pool struct{ ch chan *Conn }

func NewPool(n int) *Pool {
	p := &Pool{ch: make(chan *Conn, n)}
	for i := 1; i <= n; i++ {
		p.ch <- &Conn{ID: i}
	}
	return p
}

var ErrTimeout = errors.New("bo'sh ulanish yo'q")

func (p *Pool) Acquire(wait time.Duration) (*Conn, error) {
	select {
	case c := <-p.ch:
		return c, nil
	case <-time.After(wait):
		return nil, ErrTimeout
	}
}

func (p *Pool) Release(c *Conn) { p.ch <- c }

func main() {
	p := NewPool(2)
	a, _ := p.Acquire(time.Second)
	b, _ := p.Acquire(time.Second)
	fmt.Println("olindi:", a.ID, b.ID)

	if _, err := p.Acquire(10 * time.Millisecond); err != nil {
		fmt.Println("uchinchisi:", err)
	}

	p.Release(a)
	c, _ := p.Acquire(time.Second)
	fmt.Println("qaytarilgandan keyin olindi:", c.ID)
}

