)

type Sender interface {
	Send(to, msg string) error
}

// Haqiqiy sender: dastlabki 2 urinishda xato beradi
type flakySMS struct{ calls int }

func (f *flakySMS) Send(to, msg string) error {
	f.calls++
	if f.calls < 3 {
		return errors.New("tarmoq xatosi")
	}
	fmt.Printf("  SMS yuborildi: %s <- %q\n", to, msg)
	return nil
}

type retrySender struct {
	next     Sender
	attempts int
}

func (r retrySender) Send(to, msg string) error {
	var err error
	for i := 1; i <= r.attempts; i++ {
		if err = r.next.Send(to, msg); err == nil {
			return nil
		}
		fmt.Printf("  urinish %d: %v\n", i, err)
	}
	return fmt.Errorf("%d urinishdan keyin: %w", r.attempts, err)
}

type logSender struct{ next Sender }

func (l logSender) Send(to, msg string) error {
	fmt.Println("-> Send", to)
	err := l.next.Send(to, msg)
	fmt.Println("<- natija:", err)
	return err
}

func main() {
	var s Sender = logSender{retrySender{next: &flakySMS{}, attempts: 3}}
	s.Send("+998901112233", "kod: 4821")

	fmt.Println()
	s = logSender{retrySender{next: &flakySMS{}, attempts: 2}}
	s.Send("+998907778899", "kod: 1234")
}

