	"strings"
)

func Logged[In, Out any](name string, f func(In) Out) func(In) Out {
	return func(in In) Out {
		out := f(in)
		fmt.Printf("%s(%v) = %v\n", name, in, out)
		return out
	}
}

func Memoized[In comparable, Out any](f func(In) Out) func(In) Out {
	cache := map[In]Out{}
	return func(in In) Out {
		if v, ok := cache[in]; ok {
			return v
		}
		v := f(in)
		cache[in] = v
		return v
	}
}

func main() {
	calls := 0
	slowSquare := func(n int) int {
		calls++
		return n * n
	}

	square := Logged("square", Memoized(slowSquare))
	square(4)
	square(4)
	square(5)
	fmt.Println("haqiqiy hisoblashlar:", calls)

	upper := Logged("upper", strings.ToUpper)
	upper("go")
}

