import (
	"errors"
	"fmt"
)

type Inventory struct{ stock map[string]int }

func (i *Inventory) Reserve(sku string, qty int) error {
	if i.stock[sku] < qty {
		return fmt.Errorf("omborda %s yetarli emas (%d bor)", sku, i.stock[sku])
	}
	i.stock[sku] -= qty
	return nil
}

func (i *Inventory) Release(sku string, qty int) { i.stock[sku] += qty }

type Payments struct{ balance map[string]int }

func (p *Payments) Charge(user string, amount int) error {
	if p.balance[user] < amount {
		return errors.New("mablag' yetarli emas")
	}
	p.balance[user] -= amount
	return nil
}

type Shipping struct{ next int }

func (s *Shipping) Schedule(user, sku string) string {
	s.next++
	return fmt.Sprintf("TRK-%03d", s.next)
}

// OrderFacade — quyi tizimlar ustidagi yagona kirish nuqtasi
type OrderFacade struct {
	inv  *Inventory
	pay  *Payments
	ship *Shipping
}

func (f *OrderFacade) PlaceOrder(user, sku string, qty, price int) (string, error) {
	if err := f.inv.Reserve(sku, qty); err != nil {
		return "", fmt.Errorf("buyurtma: %w", err)
	}
	if err := f.pay.Charge(user, qty*price); err != nil {
		f.inv.Release(sku, qty) // kompensatsiya
		return "", fmt.Errorf("buyurtma: %w", err)
	}
	return f.ship.Schedule(user, sku), nil
}

func main() {
	inv := &Inventory{stock: map[string]int{"book": 5}}
	shop := &OrderFacade{
		inv:  inv,
		pay:  &Payments{balance: map[string]int{"ali": 100_000, "vali": 10_000}},
		ship: &Shipping{},
	}
	order := func(user string, qty int) {
		trk, err := shop.PlaceOrder(user, "book", qty, 30_000)
		if err != nil {
			fmt.Println(user+":", err)
			return
		}
		fmt.Println(user+": yuborildi", trk)
	}
	order("ali", 2)
	order("vali", 1)
	order("ali", 10)
	fmt.Println("omborda qoldi:", inv.stock["book"])
}

