func (n Num) Eval() float64  { return float64(n) }
func (n Num) String() string { return fmt.Sprint(float64(n)) }

type BinOp struct {
	Op   byte
	L, R Expr
}

func (b BinOp) Eval() float64 {
	l, r := b.L.Eval(), b.R.Eval()
	switch b.Op {
	case '+':
		return l + r
	case '-':
		return l - r
	case '*':
		return l * r
	case '/':
		return l / r
	}
	panic("noma'lum operator: " + string(b.Op))
}

