	e := BinOp{'/', BinOp{'*', BinOp{'+', Num(2), Num(3)}, BinOp{'-', Num(10), Num(4)}}, Num(3)}
	fmt.Println(e, "=", e.Eval())

	sum := BinOp{'+', Num(1.5), Num(2.25)}
	fmt.Println(sum, "=", sum.Eval())
}

