import (
	"fmt"
	"sync"
)

type RateService interface {
	Rate(currency string) (float64, error)
}

// Sekin tashqi API (soxta)
type remoteRates struct{ calls int }

func (r *remoteRates) Rate(cur string) (float64, error) {
	r.calls++
	rates := map[string]float64{"USD": 12650, "EUR": 13700}
	v, ok := rates[cur]
	if !ok {
		return 0, fmt.Errorf("kurs topilmadi: %s", cur)
	}
	return v, nil
}

type cachingProxy struct {
	mu    sync.Mutex
	next  RateService
	cache map[string]float64
}

func newCachingProxy(next RateService) *cachingProxy {
	return &cachingProxy{next: next, cache: map[string]float64{}}
}

func (c *cachingProxy) Rate(cur string) (float64, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if v, ok := c.cache[cur]; ok {
		return v, nil
	}
	v, err := c.next.Rate(cur)
	if err != nil {
		return 0, err // xatolar keshlanmaydi
	}
	c.cache[cur] = v
	return v, nil
}

func main() {
	remote := &remoteRates{}
	var svc RateService = newCachingProxy(remote)

	for _, cur := range []string{"USD", "EUR", "USD", "GBP", "USD", "GBP"} {
		v, err := svc.Rate(cur)
		if err != nil {
			fmt.Println(cur, "xato:", err)
			continue
		}
