import "fmt"

type DiscountStrategy interface {
	Apply(total int) int
}

type NoDiscount struct{}
type Percent struct{ P int }
type Fixed struct{ Amount, MinTotal int }

func (NoDiscount) Apply(t int) int { return t }
func (p Percent) Apply(t int) int  { return t - t*p.P/100 }
func (f Fixed) Apply(t int) int {
	if t < f.MinTotal {
		return t
	}
	return t - f.Amount
}

type Cart struct {
	items    []int
	discount DiscountStrategy
}

func (c *Cart) Total() int {
	sum := 0
	for _, p := range c.items {
		sum += p
	}
	if c.discount == nil {
		return sum
	}
	return c.discount.Apply(sum)
}

func main() {
	cart := &Cart{items: []int{120_000, 80_000}}
	strategies := []DiscountStrategy{
		NoDiscount{},
		Percent{P: 15},
		Fixed{Amount: 50_000, MinTotal: 150_000},
		Fixed{Amount: 50_000, MinTotal: 500_000},
	}
	for _, s := range strategies {
		cart.discount = s
		fmt.Printf("%T%+v: %d\n", s, s, cart.Total())
	}
}

