type Encoder func([]byte) string

var encoders = map[string]Encoder{
	"hex":    hex.EncodeToString,
	"base64": base64.StdEncoding.EncodeToString, // metod qiymati ham strategiya
	"sha256": func(b []byte) string {
		sum := sha256.Sum256(b)
