type subscriber struct {
	id int
	fn func(string)
}

type EventBus struct {
	nextID int
	subs   map[string][]subscriber
}

func (b *EventBus) Subscribe(topic string, fn func(string)) (unsubscribe func()) {
	if b.subs == nil {
		b.subs = map[string][]subscriber{}
	}
	b.nextID++
	id := b.nextID
	b.subs[topic] = append(b.subs[topic], subscriber{id, fn})
	return func() {
		b.subs[topic] = slices.DeleteFunc(b.subs[topic], func(s subscriber) bool { return s.id == id })
	}
}

func (b *EventBus) Publish(topic, data string) {
	for _, s := range b.subs[topic] {
		s.fn(data)
	}
}

func main() {
	var bus EventBus
	bus.Subscribe("order.created", func(id string) { fmt.Println("  email: buyurtma", id, "qabul qilindi") })
	stopSMS := bus.Subscribe("order.created", func(id string) { fmt.Println("  sms: buyurtma", id) })
	bus.Subscribe("order.paid", func(id string) { fmt.Println("  ombor: jo'natishga tayyorlash", id) })

	fmt.Println("publish order.created #1")
	bus.Publish("order.created", "#1")

	stopSMS()
	fmt.Println("sms obunasi bekor qilindi; publish order.created #2")
	bus.Publish("order.created", "#2")

