import (
	"fmt"
	"sync"
)

type Event struct {
	Name  string
	Value int
}

type Broker struct {
	mu   sync.Mutex
	subs []chan Event
}

func (b *Broker) Subscribe(buf int) <-chan Event {
	ch := make(chan Event, buf)
	b.mu.Lock()
	b.subs = append(b.subs, ch)
	b.mu.Unlock()
	return ch
}

func (b *Broker) Publish(e Event) {
	b.mu.Lock()
	defer b.mu.Unlock()
	for _, ch := range b.subs {
		ch <- e
	}
}

// Close — obunachilarga "boshqa hodisa yo'q" signalini beradi
func (b *Broker) Close() {
	b.mu.Lock()
	defer b.mu.Unlock()
	for _, ch := range b.subs {
		close(ch)
	}
}

func main() {
	var b Broker
	logger, stats := b.Subscribe(4), b.Subscribe(4)

	var names []string
	total := 0
	var wg sync.WaitGroup
	wg.Go(func() {
		for e := range logger {
			names = append(names, e.Name)
		}
	})
	wg.Go(func() {
		for e := range stats {
			total += e.Value
		}
	})

	b.Publish(Event{"click", 1})
	b.Publish(Event{"view", 5})
	b.Publish(Event{"buy", 100})
	b.Close()
	wg.Wait()

	fmt.Println("logger ko'rdi:", names)
	fmt.Println("stats hisobladi:", total)
}

