import "fmt"

type Editor struct{ text string }

type Command interface {
	Do(e *Editor)
	Undo(e *Editor)
}

type Insert struct{ s string }

func (c Insert) Do(e *Editor)   { e.text += c.s }
func (c Insert) Undo(e *Editor) { e.text = e.text[:len(e.text)-len(c.s)] }

// DeleteLast — o'chirgan matnini Undo uchun eslab qoladi
type DeleteLast struct {
	n       int
	removed string
}

func (c *DeleteLast) Do(e *Editor) {
	c.removed = e.text[len(e.text)-c.n:]
	e.text = e.text[:len(e.text)-c.n]
}
func (c *DeleteLast) Undo(e *Editor) { e.text += c.removed }

type History struct {
	ed   *Editor
	done []Command
}

func (h *History) Run(c Command) {
	c.Do(h.ed)
	h.done = append(h.done, c)
	fmt.Printf("%-17T %q\n", c, h.ed.text)
}

func (h *History) Undo() {
	if len(h.done) == 0 {
		return
	}
	last := h.done[len(h.done)-1]
	h.done = h.done[:len(h.done)-1]
	last.Undo(h.ed)
	fmt.Printf("%-17s %q\n", "undo", h.ed.text)
}

func main() {
	h := &History{ed: &Editor{}}
	h.Run(Insert{"Salom"})
	h.Run(Insert{", dunyo"})
	h.Run(&DeleteLast{n: 5})
	h.Undo()
	h.Undo()
	h.Run(Insert{"!"})
}

