package main

import (
	"fmt"
	"unicode"
)

type Token struct {
	Kind string
	Val  string
}

type lexer struct {
	input  []rune
	start  int
	pos    int
	tokens []Token
}

type stateFn func(*lexer) stateFn

func (l *lexer) emit(kind string) {
	l.tokens = append(l.tokens, Token{kind, string(l.input[l.start:l.pos])})
	l.start = l.pos
}

func (l *lexer) acceptWhile(ok func(rune) bool) {
	for l.pos < len(l.input) && ok(l.input[l.pos]) {
		l.pos++
	}
}

func lexAny(l *lexer) stateFn {
	l.acceptWhile(unicode.IsSpace)
	l.start = l.pos
	if l.pos >= len(l.input) {
		return nil // tamom
	}
	switch r := l.input[l.pos]; {
	case unicode.IsDigit(r):
		return lexNumber
	case unicode.IsLetter(r):
		return lexIdent
	default:
		l.pos++
		l.emit("OP")
		return lexAny
	}
}

func lexNumber(l *lexer) stateFn {
	l.acceptWhile(unicode.IsDigit)
	l.emit("NUM")
	return lexAny
}

func lexIdent(l *lexer) stateFn {
	l.acceptWhile(func(r rune) bool { return unicode.IsLetter(r) || unicode.IsDigit(r) })
	l.emit("IDENT")
	return lexAny
}

func main() {
	l := &lexer{input: []rune("narx = 1200 * soni2 + 50")}
	for state := stateFn(lexAny); state != nil; {
		state = state(l)
	}
	for _, t := range l.tokens {
		fmt.Printf("%-5s %q\n", t.Kind, t.Val)
	}
}

