type Rule func(pw string) error

func minLen(n int) Rule {
	return func(pw string) error {
		if len([]rune(pw)) < n {
			return fmt.Errorf("kamida %d belgi", n)
		}
		return nil
	}
}

func has(f func(rune) bool, msg string) Rule {
	return func(pw string) error {
		if !strings.ContainsFunc(pw, f) {
			return errors.New(msg)
		}
		return nil
	}
}

func notCommon(pw string) error {
	if strings.EqualFold(pw, "Password1") {
		return errors.New("juda keng tarqalgan parol")
	}
	return nil
}

func Validate(pw string, rules ...Rule) error {
	for _, r := range rules {
		if err := r(pw); err != nil {
			return err
		}
	}
	return nil
}

func main() {
	rules := []Rule{
		minLen(8),
		has(unicode.IsDigit, "kamida bitta raqam"),
		has(unicode.IsUpper, "kamida bitta katta harf"),
		notCommon,
	}
	for _, pw := range []string{"abc", "abcdefgh", "abcdefg1", "Password1", "Toshkent2026"} {
		if err := Validate(pw, rules...); err != nil {
			fmt.Printf("%-13s rad: %v\n", pw, err)
			continue
		}
		fmt.Printf("%-13s qabul\n", pw)
	}
}

