package main

import (
	"errors"
	"fmt"
	"time"
)

var ErrOpen = errors.New("breaker ochiq: so'rov yuborilmadi")

type state int

const (
	closed state = iota
	open
	halfOpen
)

func (s state) String() string { return [...]string{"closed", "open", "half-open"}[s] }

type Breaker struct {
	state     state
	failures  int
	threshold int
	cooldown  time.Duration
	openedAt  time.Time
	now       func() time.Time
}

func (b *Breaker) Call(fn func() error) error {
	if b.state == open {
		if b.now().Sub(b.openedAt) < b.cooldown {
			return ErrOpen
		}
		b.state = halfOpen // bitta sinov so'rovi
	}
	if err := fn(); err != nil {
		b.failures++
		if b.state == halfOpen || b.failures >= b.threshold {
			b.state, b.openedAt = open, b.now()
		}
		return err
	}
	b.state, b.failures = closed, 0
	return nil
}

func main() {
	clock := time.Date(2026, 1, 15, 12, 0, 0, 0, time.UTC)
	b := &Breaker{threshold: 2, cooldown: 30 * time.Second, now: func() time.Time { return clock }}

	fail := func() error { return errors.New("503") }
	ok := func() error { return nil }

	steps := []struct {
		after time.Duration
		fn    func() error
	}{
		{0, fail}, {time.Second, fail}, {time.Second, ok},
		{40 * time.Second, fail}, {time.Second, ok},
		{40 * time.Second, ok}, {time.Second, ok},
	}
	for i, s := range steps {
		clock = clock.Add(s.after)
		err := b.Call(s.fn)
		fmt.Printf("%d. %-6s err=%v\n", i+1, b.state, err)
	}
}

package main

import (
	"errors"
	"fmt"
	"strings"
)

type User struct {
	ID   int
	Name string
}

var ErrNotFound = errors.New("topilmadi")

type UserRepo interface {
	Get(id int) (User, error)
}

type dbRepo struct {
	rows    map[int]User
	queries int
}

func (r *dbRepo) Get(id int) (User, error) {
	r.queries++
	u, ok := r.rows[id]
	if !ok {
		return User{}, fmt.Errorf("user %d: %w", id, ErrNotFound)
	}
	return u, nil
}

type cachedRepo struct {
	next  UserRepo
	cache map[int]User
}

func (c *cachedRepo) Get(id int) (User, error) {
	if u, ok := c.cache[id]; ok {
		return u, nil
	}
	u, err := c.next.Get(id)
	if err == nil {
		c.cache[id] = u
	}
	return u, err
}

type metricRepo struct {
	next         UserRepo
	calls, fails int
}

func (m *metricRepo) Get(id int) (User, error) {
	m.calls++
	u, err := m.next.Get(id)
	if err != nil {
		m.fails++
	}
	return u, err
}

func main() {
	db := &dbRepo{rows: map[int]User{1: {1, "Ali"}, 2: {2, "Vali"}}}
	metrics := &metricRepo{next: &cachedRepo{next: db, cache: map[int]User{}}}
	var repo UserRepo = metrics

	var got []string
	for _, id := range []int{1, 2, 1, 1, 3, 2} {
		u, err := repo.Get(id)
		if errors.Is(err, ErrNotFound) {
			got = append(got, "?")
			continue
		}
		got = append(got, u.Name)
	}
	fmt.Println("natijalar:", strings.Join(got, " "))
	fmt.Printf("chaqiruvlar=%d xatolar=%d DB so'rovlari=%d\n", metrics.calls, metrics.fails, db.queries)
}

