type Store interface {
	Put(key, val string)
	Get(key string) (string, bool)
}

type Driver func(dsn string) (Store, error)

var drivers = map[string]Driver{}

// Register — drayver paketlari init() ichida chaqiradi
func Register(name string, d Driver) {
	if _, dup := drivers[name]; dup {
		panic("storage: takroriy drayver " + name)
	}
	drivers[name] = d
}

func Drivers() []string { return slices.Sorted(maps.Keys(drivers)) }

func Open(name, dsn string) (Store, error) {
	d, ok := drivers[name]
	if !ok {
		return nil, fmt.Errorf("storage: noma'lum drayver %q (import qilishni unutdingizmi?)", name)
	}
	return d(dsn)
}

