var errNoLimit = errors.New("konteyner limiti yo'q")

// limitFromCgroup — memory.max matnidan GOMEMLIMIT qiymatini hisoblaydi
func limitFromCgroup(content string, ratio float64) (int64, error) {
	s := strings.TrimSpace(content)
	if s == "max" {
		return 0, errNoLimit
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n <= 0 {
		return 0, fmt.Errorf("noto'g'ri memory.max %q", s)
	}
	return int64(float64(n) * ratio), nil
}

func main() {
	for _, content := range []string{"1073741824\n", "max\n", "1G"} {
		limit, err := limitFromCgroup(content, 0.9)
		if err != nil {
			fmt.Println("xato:", err)
			continue
		}
		debug.SetMemoryLimit(limit)
		fmt.Printf("memory.max=%s -> GOMEMLIMIT=%dMiB\n", strings.TrimSpace(content), limit>>20)
	}
	fmt.Println("o'rnatilgan MiB:", debug.SetMemoryLimit(-1)>>20)
}

package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

var units = []struct {
	suffix string
	mul    int64
}{
	{"TiB", 1 << 40}, {"GiB", 1 << 30}, {"MiB", 1 << 20}, {"KiB", 1 << 10}, {"B", 1},
}

func parseMemLimit(s string) (int64, error) {
	if s == "off" {
		return math.MaxInt64, nil
	}
	mul := int64(1)
	for _, u := range units {
		if strings.HasSuffix(s, u.suffix) {
			s, mul = strings.TrimSuffix(s, u.suffix), u.mul
			break
		}
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 || n > math.MaxInt64/mul {
		return 0, fmt.Errorf("noto'g'ri GOMEMLIMIT")
	}
	return n * mul, nil
}

func main() {
	for _, v := range []string{"512MiB", "2GiB", "1048576", "64KiB", "off", "500MB", "-1GiB"} {
		n, err := parseMemLimit(v)
		switch {
		case err != nil:
			fmt.Printf("%-8s -> %v\n", v, err)
		case n == math.MaxInt64:
			fmt.Printf("%-8s -> limitsiz\n", v)
		default:
			fmt.Printf("%-8s -> %d bayt\n", v, n)
		}
	}
}

