	"strconv"
	"sync"
	"testing"
)

var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

func render(buf *bytes.Buffer, id int, name string) int {
	buf.WriteString("user:")
	buf.Write(strconv.AppendInt(buf.AvailableBuffer(), int64(id), 10))
	buf.WriteByte(' ')
	buf.WriteString(name)
	return buf.Len()
}

func renderNew(id int, name string) int {
	return render(new(bytes.Buffer), id, name)
}

func renderPooled(id int, name string) int {
	buf := bufPool.Get().(*bytes.Buffer)
	buf.Reset()
	n := render(buf, id, name)
	bufPool.Put(buf)
	return n
}

func main() {
	fmt.Println("yangi bufer:", testing.AllocsPerRun(1000, func() { _ = renderNew(4217, "ali") }))
	fmt.Println("pool bilan:", testing.AllocsPerRun(1000, func() { _ = renderPooled(4217, "ali") }))
	fmt.Println("uzunlik:", renderPooled(4217, "ali"))
}

