import (
	"bytes"
	"fmt"
	"sync"
	"sync/atomic"
)

const maxPooledCap = 64 << 10 // 64 KiB

type BufferPool struct {
	pool    sync.Pool
	dropped atomic.Int64
}

func NewBufferPool() *BufferPool {
	bp := &BufferPool{}
	bp.pool.New = func() any { return new(bytes.Buffer) }
	return bp
}

func (bp *BufferPool) Get() *bytes.Buffer { return bp.pool.Get().(*bytes.Buffer) }

func (bp *BufferPool) Put(b *bytes.Buffer) {
	if b.Cap() > maxPooledCap {
		bp.dropped.Add(1) // juda katta — GC'ga qoldiramiz
		return
	}
	b.Reset()
	bp.pool.Put(b)
}

func main() {
	bp := NewBufferPool()

	small := bp.Get()
	small.WriteString("kichik javob")
	bp.Put(small)

	big := bp.Get()
	big.Write(make([]byte, 1<<20)) // 1 MiB lik javob
	bp.Put(big)

	again := bp.Get()
	fmt.Println("tashlangan katta buferlar:", bp.dropped.Load())
	fmt.Println("qayta olingan bufer bo'sh:", again.Len() == 0)
	fmt.Println("sig'imi chegarada:", again.Cap() <= maxPooledCap)
}

