import (
	"fmt"
	"runtime"
	"sync"
	"time"
	"weak"
)

type Image struct {
	Name   string
	pixels [4096]byte
}

type Cache struct {
	mu      sync.Mutex
	items   map[string]weak.Pointer[Image]
	evicted chan string
}

func (c *Cache) Get(name string) (*Image, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if w, ok := c.items[name]; ok {
		if img := w.Value(); img != nil {
			return img, true // kesh hit
		}
	}
	img := &Image{Name: name} // "diskdan yuklash"
	c.items[name] = weak.Make(img)
	runtime.AddCleanup(img, func(key string) {
		c.mu.Lock()
		if w, ok := c.items[key]; ok && w.Value() == nil {
			delete(c.items, key)
		}
		c.mu.Unlock()
		c.evicted <- key
	}, name)
	return img, false
}

func main() {
	c := &Cache{items: map[string]weak.Pointer[Image]{}, evicted: make(chan string, 1)}

	img1, hit1 := c.Get("logo.png")
	img2, hit2 := c.Get("logo.png")
	fmt.Println("hit:", hit1, hit2, "bir obyekt:", img1 == img2)
	runtime.KeepAlive(img1)
	runtime.KeepAlive(img2)

	runtime.GC() // rasmni hech kim ishlatmayapti
	select {
	case key := <-c.evicted:
		fmt.Println("keshdan chiqarildi:", key)
	case <-time.After(2 * time.Second):
		fmt.Println("cleanup ishlamadi")
	}
	c.mu.Lock()
	fmt.Println("keshdagi elementlar:", len(c.items))
	c.mu.Unlock()
}

