	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return fmt.Sprintf("butun son %d", v.Int())
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return fmt.Sprintf("ishorasiz son %d", v.Uint())
	case reflect.Float32, reflect.Float64:
		return fmt.Sprintf("kasr son %.2f", v.Float())
	case reflect.String:
		return fmt.Sprintf("satr, uzunligi %d", v.Len())
	case reflect.Slice, reflect.Array:
		return fmt.Sprintf("%s, %d ta element", v.Kind(), v.Len())
	case reflect.Map:
		return fmt.Sprintf("map, %d ta kalit", v.Len())
	case reflect.Pointer:
		return "ko'rsatkich -> " + describe(v.Elem().Interface())
	default:
		return "boshqa: " + v.Kind().String()
	}
}

