import (
	"fmt"
	"reflect"
)

func SetField(obj any, name string, value any) error {
	v := reflect.ValueOf(obj)
	if v.Kind() != reflect.Pointer || v.Elem().Kind() != reflect.Struct {
		return fmt.Errorf("struct'ga ko'rsatkich kerak, %T berildi", obj)
	}
	f := v.Elem().FieldByName(name)
	if !f.IsValid() {
		return fmt.Errorf("%q maydoni yo'q", name)
	}
	if !f.CanSet() {
		return fmt.Errorf("%q maydonini o'zgartirib bo'lmaydi", name)
	}
	val := reflect.ValueOf(value)
	if !val.Type().AssignableTo(f.Type()) {
		return fmt.Errorf("%q: %s kerak, %s berildi", name, f.Type(), val.Type())
	}
	f.Set(val)
	return nil
}

type User struct {
	Name  string
	Age   int
	email string
}

func main() {
	u := User{}
	fmt.Println(SetField(&u, "Name", "Aziza"))
	fmt.Println(SetField(&u, "Age", 28))
	fmt.Println(SetField(&u, "Age", "28"))
	fmt.Println(SetField(&u, "Phone", "+998"))
	fmt.Println(SetField(&u, "email", "a@b.uz"))
	fmt.Println(SetField(u, "Name", "X"))
	fmt.Printf("%+v\n", u)
}

