func signature(f any) string {
	t := reflect.TypeOf(f)
	ins := make([]string, t.NumIn())
	for i := range t.NumIn() {
		ins[i] = t.In(i).String()
	}
	outs := make([]string, t.NumOut())
	for i := range t.NumOut() {
		outs[i] = t.Out(i).String()
	}
	return fmt.Sprintf("in=%v out=%v variadic=%v", ins, outs, t.IsVariadic())
}

