import (
	"fmt"
	"reflect"
	"strings"
)

func SafeCall(fn any, args ...any) (results []any, err error) {
	fv := reflect.ValueOf(fn)
	if fv.Kind() != reflect.Func {
		return nil, fmt.Errorf("funksiya emas: %T", fn)
	}
	ft := fv.Type()
	if ft.IsVariadic() || len(args) != ft.NumIn() {
		return nil, fmt.Errorf("%d ta argument kerak, %d ta berildi", ft.NumIn(), len(args))
	}
	in := make([]reflect.Value, len(args))
	for i, a := range args {
		want := ft.In(i)
		av := reflect.ValueOf(a)
		if !av.IsValid() {
			av = reflect.Zero(want) // nil -> kerakli tipning nol qiymati
		}
		if !av.Type().AssignableTo(want) {
			return nil, fmt.Errorf("%d-argument: %s kerak, %s berildi", i+1, want, av.Type())
		}
		in[i] = av
	}
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("funksiya ichida panic: %v", r)
		}
	}()
	for _, o := range fv.Call(in) {
		results = append(results, o.Interface())
	}
	return results, nil
}

func divide(a, b int) int { return a / b }

func main() {
	fmt.Println(SafeCall(divide, 10, 2))
	fmt.Println(SafeCall(divide, 10))
	fmt.Println(SafeCall(divide, 10, "2"))
	fmt.Println(SafeCall(divide, 10, 0))
	fmt.Println(SafeCall(42))
	fmt.Println(SafeCall(strings.ToUpper, "salom"))
	fmt.Println(SafeCall(func(p *int) bool { return p == nil }, nil))
}

