import (
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

func Logged[F any](name string, fn F) F {
	fv := reflect.ValueOf(fn)
	wrapper := reflect.MakeFunc(fv.Type(), func(args []reflect.Value) []reflect.Value {
		out := fv.Call(args)
		fmt.Printf("  log: %s(%s) = %s\n", name, join(args), join(out))
		return out
	})
	return wrapper.Interface().(F)
}

func join(vs []reflect.Value) string {
	parts := make([]string, len(vs))
	for i, v := range vs {
		if v.Kind() == reflect.String {
			parts[i] = strconv.Quote(v.String())
		} else {
			parts[i] = fmt.Sprint(v.Interface())
		}
	}
	return strings.Join(parts, ", ")
}

func main() {
	add := Logged("add", func(a, b int) int { return a + b })
	upper := Logged("upper", strings.ToUpper)
	atoi := Logged("atoi", strconv.Atoi)

	fmt.Println("natija:", add(2, 3)*10)
	fmt.Println("natija:", upper("salom"))
	n, err := atoi("x")
	fmt.Println("natija:", n, err != nil)
}

