import (
	"fmt"
	"reflect"
	"strings"
	"sync"
)

type fieldInfo struct {
	Name  string
	Index int
}

var cache sync.Map // reflect.Type -> []fieldInfo

func fieldsOf(t reflect.Type) []fieldInfo {
	if v, ok := cache.Load(t); ok {
		return v.([]fieldInfo)
	}
	fmt.Println("  (tahlil qilinmoqda:", t.String()+")")
	var fs []fieldInfo
	for i := range t.NumField() {
		if f := t.Field(i); f.IsExported() {
			fs = append(fs, fieldInfo{Name: f.Name, Index: i})
		}
	}
	v, _ := cache.LoadOrStore(t, fs)
	return v.([]fieldInfo)
}

func Dump(x any) {
	v := reflect.ValueOf(x)
	var parts []string
	for _, f := range fieldsOf(v.Type()) {
		parts = append(parts, fmt.Sprintf("%s=%v", f.Name, v.Field(f.Index)))
	}
	fmt.Println(strings.Join(parts, " "))
}

type User struct {
	ID   int
	Name string
	pass string
}

type Item struct {
	SKU   string
	Price float64
}

