	Zip  string
}

type Contact struct {
	Kind  string
	Value string
}

type Customer struct {
	Name     string
	Age      int
	Address  *Address
	Contacts []Contact
	Labels   map[string]string
	Manager  *Customer
}

func walk(path string, v reflect.Value, visit func(string, reflect.Value)) {
	switch v.Kind() {
	case reflect.Pointer, reflect.Interface:
		if v.IsNil() {
			visit(path, v)
			return
		}
		walk(path, v.Elem(), visit)
	case reflect.Struct:
		t := v.Type()
		for i := range v.NumField() {
			if t.Field(i).IsExported() {
				walk(path+"."+t.Field(i).Name, v.Field(i), visit)
			}
		}
	case reflect.Slice, reflect.Array:
		for i := range v.Len() {
			walk(fmt.Sprintf("%s[%d]", path, i), v.Index(i), visit)
		}
	case reflect.Map:
		keys := v.MapKeys()
		slices.SortFunc(keys, func(a, b reflect.Value) int { return cmp.Compare(a.String(), b.String()) })
		for _, k := range keys {
			walk(fmt.Sprintf("%s[%q]", path, k.String()), v.MapIndex(k), visit)
		}
	default:
		visit(path, v)
	}
}

func main() {
	c := Customer{
		Name:     "Malika",
		Age:      31,
		Address:  &Address{City: "Buxoro", Zip: "200100"},
		Contacts: []Contact{{"tel", "+998901234567"}, {"email", "m@example.uz"}},
		Labels:   map[string]string{"tier": "gold", "lang": "uz"},
	}
	walk("Customer", reflect.ValueOf(c), func(p string, v reflect.Value) {
		if v.Kind() == reflect.Pointer && v.IsNil() {
			fmt.Printf("%-27s = nil\n", p)
			return
		}
		fmt.Printf("%-27s = %v\n", p, v)
	})
}

