import (
	"encoding"
	"fmt"
	"log/slog"
	"reflect"
	"strconv"
	"strings"
	"time"
)

func setFromString(f reflect.Value, s string) error {
	// 1) Maxsus tiplar — Kind'dan OLDIN (Duration ham Kind=int64)
	if u, ok := f.Addr().Interface().(encoding.TextUnmarshaler); ok {
		return u.UnmarshalText([]byte(s))
	}
	// 2) Qolganlari Kind bo'yicha; Bits() — maydon necha bitli
	var val any
	var err error
	switch {
	case f.Type() == reflect.TypeFor[time.Duration]():
		val, err = time.ParseDuration(s)
	case f.Kind() == reflect.String:
		val = s
	case f.Kind() == reflect.Bool:
		val, err = strconv.ParseBool(s)
	case f.CanInt():
		val, err = strconv.ParseInt(s, 10, f.Type().Bits())
	case f.CanUint():
		val, err = strconv.ParseUint(s, 10, f.Type().Bits())
	case f.CanFloat():
		val, err = strconv.ParseFloat(s, f.Type().Bits())
	case f.Kind() == reflect.Slice:
		parts := strings.Split(s, ",")
		sl := reflect.MakeSlice(f.Type(), len(parts), len(parts))
		for i, p := range parts {
			if err := setFromString(sl.Index(i), strings.TrimSpace(p)); err != nil {
				return fmt.Errorf("[%d]: %w", i, err)
			}
		}
		f.Set(sl)
		return nil
	default:
		return fmt.Errorf("qo'llab-quvvatlanmaydigan tip: %s", f.Type())
	}
	if err != nil {
		return err
	}
	// int64 -> uint16, float64 -> float32 kabi moslash
	f.Set(reflect.ValueOf(val).Convert(f.Type()))
	return nil
}

type Settings struct {
	Name    string
	Port    uint16
	Debug   bool
	Ratio   float32
	Timeout time.Duration
	Ports   []int
	Level   slog.Level // *slog.Level — encoding.TextUnmarshaler
}

func main() {
	var s Settings
	v := reflect.ValueOf(&s).Elem()
	input := [][2]string{
		{"Name", "api"}, {"Port", "8080"}, {"Debug", "true"}, {"Ratio", "0.75"},
		{"Timeout", "1m30s"}, {"Ports", "80, 443"}, {"Level", "warn"},
		{"Port", "70000"}, {"Debug", "ha"}, {"Ports", "80,x"},
	}
	for _, kv := range input {
		if err := setFromString(v.FieldByName(kv[0]), kv[1]); err != nil {
			fmt.Printf("%s=%q: %v\n", kv[0], kv[1], err)
		}
	}
	fmt.Printf("%+v\n", s)
}

