import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"time"
	"unicode"
)

type DBConfig struct {
	Host     string
	MaxConns int
}

type Config struct {
	Env     string
	Timeout time.Duration
	DB      DBConfig
}

func toSnake(name string) string {
	var b strings.Builder
	for i, r := range name {
		if i > 0 && unicode.IsUpper(r) && !unicode.IsUpper(rune(name[i-1])) {
			b.WriteByte('_')
		}
		b.WriteRune(unicode.ToUpper(r))
	}
	return b.String()
}

func parse(f reflect.Value, s string) (err error) {
	var val any
	switch {
	case f.Type() == reflect.TypeFor[time.Duration]():
		val, err = time.ParseDuration(s)
	case f.Kind() == reflect.String:
		val = s
	case f.Kind() == reflect.Int:
		val, err = strconv.Atoi(s)
	default:
		return fmt.Errorf("tip qo'llanmaydi: %s", f.Type())
	}
	if err == nil {
		f.Set(reflect.ValueOf(val).Convert(f.Type()))
	}
	return err
}

func load(prefix string, v reflect.Value, lookup func(string) (string, bool)) error {
	var errs []error
	for i := range v.NumField() {
		sf := v.Type().Field(i)
		key := prefix + "_" + toSnake(sf.Name)
		if fv := v.Field(i); fv.Kind() == reflect.Struct {
			errs = append(errs, load(key, fv, lookup))
		} else if raw, ok := lookup(key); ok && fv.CanSet() { // eksport qilinmagan — CanSet=false
			if err := parse(fv, raw); err != nil {
				errs = append(errs, fmt.Errorf("%s=%q: %w", key, raw, err))
			}
		}
	}
	return errors.Join(errs...)
}

func main() {
	env := map[string]string{
		"APP_ENV": "production", "APP_TIMEOUT": "15s",
		"APP_DB_HOST": "db.internal", "APP_DB_MAX_CONNS": "ko'p",
	}
	lookup := func(k string) (string, bool) { v, ok := env[k]; return v, ok }
	cfg := Config{Env: "dev", Timeout: 5 * time.Second, DB: DBConfig{Host: "localhost", MaxConns: 10}}
	if err := load("APP", reflect.ValueOf(&cfg).Elem(), lookup); err != nil {
		fmt.Println("xato:", err)
	}
	fmt.Printf("%+v\n", cfg)
}

