	"strconv"
	"strings"
)

type Item struct {
	SKU string `validate:"required"`
	Qty int    `validate:"min=1,max=100"`
}

type Order struct {
	Customer string  `validate:"required,min=3"`
	Email    *string `validate:"required"`
	Items    []Item  `validate:"min=1"`
	Note     string  `validate:"max=20"`
}

// size — Kind'ga qarab "o'lcham": uzunlik yoki son qiymati
func size(v reflect.Value) int64 {
	switch v.Kind() {
	case reflect.String, reflect.Slice, reflect.Map:
		return int64(v.Len())
	case reflect.Int, reflect.Int32, reflect.Int64:
		return v.Int()
	}
	return 0
}

func check(v reflect.Value, rule string) string {
	name, arg, _ := strings.Cut(rule, "=")
	n, _ := strconv.ParseInt(arg, 10, 64)
	switch {
	case name == "required" && v.IsZero():
		return "majburiy"
	case name == "min" && size(v) < n:
		return fmt.Sprintf("kamida %d (hozir %d)", n, size(v))
	case name == "max" && size(v) > n:
		return fmt.Sprintf("ko'pi bilan %d (hozir %d)", n, size(v))
	}
	return ""
}

func validate(path string, v reflect.Value) []string {
	var errs []string
	for i := range v.NumField() {
		sf, fv := v.Type().Field(i), v.Field(i)
		name := path + "." + sf.Name
		for rule := range strings.SplitSeq(sf.Tag.Get("validate"), ",") {
			if msg := check(fv, rule); msg != "" {
				errs = append(errs, name+": "+msg)
			}
		}
		if fv.Kind() == reflect.Slice && fv.Type().Elem().Kind() == reflect.Struct {
			for j := range fv.Len() {
				errs = append(errs, validate(fmt.Sprintf("%s[%d]", name, j), fv.Index(j))...)
			}
		}
	}
	return errs
}

func main() {
	email := "a@b.uz"
	good := Order{Customer: "Akmal", Email: &email, Items: []Item{{"A-1", 2}}}
	bad := Order{Customer: "Al", Items: []Item{{"", 0}, {"B-2", 500}}, Note: "iltimos, tezroq yetkazib bering"}

	fmt.Println("good:", validate("Order", reflect.ValueOf(good)))
	fmt.Println("bad:")
	for _, e := range validate("Order", reflect.ValueOf(bad)) {
		fmt.Println("  -", e)
	}
}

