import (
	"encoding/json"
	"fmt"
	"reflect"
	"slices"
	"strconv"
	"strings"
)

func encode(v reflect.Value) string {
	switch v.Kind() {
	case reflect.Pointer, reflect.Interface:
		if v.IsNil() {
			return "null"
		}
		return encode(v.Elem())
	case reflect.Bool, reflect.Int, reflect.Int64, reflect.Float64:
		return fmt.Sprint(v.Interface())
	case reflect.String:
		return strconv.Quote(v.String())
	case reflect.Slice:
		var parts []string
		for i := range v.Len() {
			parts = append(parts, encode(v.Index(i)))
		}
		return "[" + strings.Join(parts, ",") + "]"
	case reflect.Map:
		var parts []string
		for it := v.MapRange(); it.Next(); {
			parts = append(parts, strconv.Quote(it.Key().String())+":"+encode(it.Value()))
		}
		slices.Sort(parts) // kalitlar bo'yicha tartib
		return "{" + strings.Join(parts, ",") + "}"
	case reflect.Struct:
		var parts []string
		for i := range v.NumField() {
			f := v.Type().Field(i)
			name, opt, _ := strings.Cut(f.Tag.Get("json"), ",")
			if !f.IsExported() || name == "-" || (opt == "omitempty" && v.Field(i).IsZero()) {
				continue
			}
			if name == "" {
				name = f.Name
			}
			parts = append(parts, strconv.Quote(name)+":"+encode(v.Field(i)))
		}
		return "{" + strings.Join(parts, ",") + "}"
	}
	panic(fmt.Errorf("qo'llab-quvvatlanmaydigan tip: %s", v.Type()))
}

func Marshal(x any) (s string, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("json: %v", r)
		}
	}()
	return encode(reflect.ValueOf(x)), nil
}

type Order struct {
	ID     int            `json:"id"`
	Total  float64        `json:"total"`
	Items  []string       `json:"items"`
	Meta   map[string]any `json:"meta,omitempty"`
	Coupon *string        `json:"coupon"`
	secret string
}

func main() {
	o := Order{ID: 7, Total: 12.5, Items: []string{"choy", "non"}, Meta: map[string]any{"src": "web", "n": 2}}
	s, err := Marshal(o)
	std, _ := json.Marshal(o)
	fmt.Println(s, err)
	fmt.Println("json.Marshal bilan bir xil:", s == string(std))
	_, err = Marshal(map[string]any{"ch": make(chan int)})
	fmt.Println("xato:", err)
}

