)

func CopyFields(dst, src any) (copied []string, err error) {
	dv := reflect.ValueOf(dst)
	if dv.Kind() != reflect.Pointer || dv.Elem().Kind() != reflect.Struct {
		return nil, errors.New("dst struct'ga ko'rsatkich bo'lishi kerak")
	}
	dv = dv.Elem()
	sv := reflect.Indirect(reflect.ValueOf(src)) // *T bo'lsa T ga
	for i := range sv.NumField() {
		sf := sv.Type().Field(i)
		df := dv.FieldByName(sf.Name)
		if !sf.IsExported() || !df.IsValid() || !df.CanSet() {
			continue
		}
		val := sv.Field(i)
		switch {
		case val.Type().AssignableTo(df.Type()):
			df.Set(val)
		case val.Kind() == df.Kind() && val.CanConvert(df.Type()):
			df.Set(val.Convert(df.Type()))
		default:
			continue
		}
		copied = append(copied, sf.Name)
	}
	return copied, nil
}

