package main

import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

type Commands struct{}

func (Commands) Hello(name string) string { return "Salom, " + name + "!" }
func (Commands) Add(a, b int) string      { return strconv.Itoa(a + b) }
func (Commands) Upper(s string) string    { return strings.ToUpper(s) }

func dispatch(target any, line string) (string, error) {
	parts := strings.Fields(line)
	if len(parts) == 0 {
		return "", errors.New("bo'sh buyruq")
	}
	cmd, args := parts[0], parts[1:]
	m := reflect.ValueOf(target).MethodByName(strings.ToUpper(cmd[:1]) + cmd[1:])
	if !m.IsValid() {
		return "", fmt.Errorf("noma'lum buyruq %q", cmd)
	}
	mt := m.Type()
	if len(args) != mt.NumIn() {
		return "", fmt.Errorf("%s: %d ta argument kerak", cmd, mt.NumIn())
	}
	in := make([]reflect.Value, len(args))
	for i, a := range args {
		switch mt.In(i).Kind() {
		case reflect.String:
			in[i] = reflect.ValueOf(a)
		case reflect.Int:
			n, err := strconv.Atoi(a)
			if err != nil {
				return "", fmt.Errorf("%s: %d-argument son emas: %q", cmd, i+1, a)
			}
			in[i] = reflect.ValueOf(n)
		default:
			return "", fmt.Errorf("tip qo'llanmaydi: %s", mt.In(i))
		}
	}
	return m.Call(in)[0].String(), nil
}

func main() {
	lines := []string{"hello Dunyo", "add 2 40", "upper reflect", "add 2 x", "delete all", "hello"}
	for _, line := range lines {
		res, err := dispatch(Commands{}, line)
		if err != nil {
			fmt.Printf("%-13s -> xato: %v\n", line, err)
			continue
		}
		fmt.Printf("%-13s -> %s\n", line, res)
	}
}

package main

import (
	"cmp"
	"fmt"
	"reflect"
	"sort"
	"strings"
)

type Employee struct {
	Name   string
	Age    int
	Salary float64
	Tags   []string
}

func compare(a, b reflect.Value) int {
	switch a.Kind() {
	case reflect.String:
		return cmp.Compare(a.String(), b.String())
	case reflect.Int:
		return cmp.Compare(a.Int(), b.Int())
	case reflect.Float64:
		return cmp.Compare(a.Float(), b.Float())
	}
	return 0
}

func SortBy(slice any, spec string) error {
	desc := strings.HasPrefix(spec, "-")
	field := strings.TrimPrefix(spec, "-")
	v := reflect.ValueOf(slice)
	if v.Kind() != reflect.Slice || v.Type().Elem().Kind() != reflect.Struct {
		return fmt.Errorf("struct'lar slice'i kerak, %T berildi", slice)
	}
	sf, ok := v.Type().Elem().FieldByNameFunc(func(n string) bool { return strings.EqualFold(n, field) })
	if !ok {
		return fmt.Errorf("%q maydoni yo'q", field)
	}
	switch sf.Type.Kind() {
	case reflect.String, reflect.Int, reflect.Float64:
	default:
		return fmt.Errorf("%s bo'yicha saralab bo'lmaydi (%s)", sf.Name, sf.Type)
	}
	sort.SliceStable(slice, func(i, j int) bool {
		c := compare(v.Index(i).FieldByIndex(sf.Index), v.Index(j).FieldByIndex(sf.Index))
		return (c < 0 && !desc) || (c > 0 && desc)
	})
	return nil
}

func main() {
	staff := []Employee{{"Olim", 34, 12e6, nil}, {"Bekzod", 27, 9.5e6, nil}, {"Zarina", 41, 15e6, nil}, {"Aziz", 27, 11e6, nil}}
	for _, spec := range []string{"age", "-salary", "NAME", "email", "tags"} {
		if err := SortBy(staff, spec); err != nil {
			fmt.Printf("%-8s xato: %v\n", spec, err)
			continue
		}
		var names []string
		for _, e := range staff {
			names = append(names, e.Name)
		}
		fmt.Printf("%-8s %v\n", spec, names)
	}
	fmt.Println(SortBy(map[string]int{}, "age"))
}

