import (
	"fmt"
	"reflect"
)

func SumReflect(xs any) (float64, error) {
	v := reflect.ValueOf(xs)
	if v.Kind() != reflect.Slice {
		return 0, fmt.Errorf("slice emas: %T", xs)
	}
	var total float64
	for i := range v.Len() {
		switch e := v.Index(i); {
		case e.CanInt():
			total += float64(e.Int())
		case e.CanUint():
			total += float64(e.Uint())
		case e.CanFloat():
			total += e.Float()
		default:
			return 0, fmt.Errorf("%d-element son emas: %s", i+1, e.Type())
		}
	}
	return total, nil
}

type Number interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 | ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~float32 | ~float64
}

func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

type Money int64

func main() {
	fmt.Println(SumReflect([]int{1, 2, 3}))
	fmt.Println(SumReflect([]Money{100, 250}))
	fmt.Println(SumReflect([]float32{0.5, 0.25}))
	fmt.Println(SumReflect([]string{"a"}))
	fmt.Println(SumReflect(42))

	fmt.Println(Sum([]int{1, 2, 3}))
	m := Sum([]Money{100, 250})
	fmt.Printf("%v %T\n", m, m)
	fmt.Println(Sum([]float32{0.5, 0.25}))
	// Sum([]string{"a"}) // kompilyatsiya xatosi: string does not satisfy Number
}

