import (
	"cmp"
	"fmt"
	"reflect"
	"slices"
)

type Event struct {
	Active  bool
	ID      int64
	Kind    uint8
	Payload []byte
	Code    int16
}

func layout(t reflect.Type) {
	fmt.Printf("%s: size=%d align=%d\n", t, t.Size(), t.Align())
	var end uintptr
	for i := range t.NumField() {
		f := t.Field(i)
		if f.Offset > end {
			fmt.Printf("  %-9s offset=%-2d size=%d\n", "(padding)", end, f.Offset-end)
		}
		fmt.Printf("  %-9s offset=%-2d size=%d\n", f.Name, f.Offset, f.Type.Size())
		end = f.Offset + f.Type.Size()
	}
	if t.Size() > end {
		fmt.Printf("  %-9s offset=%-2d size=%d\n", "(oxiri)", end, t.Size()-end)
	}
}

func main() {
	t := reflect.TypeFor[Event]()
	layout(t)

	fields := make([]reflect.StructField, t.NumField())
	for i := range fields {
		fields[i] = t.Field(i)
		fields[i].Offset = 0
	}
	slices.SortStableFunc(fields, func(a, b reflect.StructField) int {
		return cmp.Compare(b.Type.Align(), a.Type.Align()) // kattadan kichikka
	})
	opt := reflect.StructOf(fields)
	fmt.Println("optimal tartib:")
	layout(opt)
}

