import (
	"fmt"
	"unsafe"
)

func BytesToString(b []byte) string {
	if len(b) == 0 {
		return ""
	}
	return unsafe.String(&b[0], len(b))
}

// Natijaga YOZISH MUMKIN EMAS: satr xotirasi faqat o'qish uchun
func StringToBytes(s string) []byte {
	return unsafe.Slice(unsafe.StringData(s), len(s))
}

func main() {
	buf := []byte("salom")
	s := BytesToString(buf) // s buf xotirasini ko'rsatadi
	fmt.Println(s, len(s))

	buf[0] = 'S' // XAVF: satr ham o'zgaradi!
	fmt.Println(s)

	safe := string(buf) // nusxa
	buf[0] = 's'
	fmt.Println("nusxa:", safe, "| unsafe:", s)

	b := StringToBytes("dunyo")
	fmt.Println(b, string(b[:3]))
	// b[0] = 'D' // aniqlanmagan xatti-harakat: literal faqat o'qiladigan xotirada

	arr := [4]int{10, 20, 30, 40}
	part := unsafe.Slice(&arr[1], 2) // ko'rsatkich + uzunlik -> slice
	fmt.Println(part, len(part), cap(part))
	fmt.Println("SliceData == &arr[1]:", unsafe.SliceData(part) == &arr[1])
}
